INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-f0e397746ff7', 'd2a4b0bbc370b7bbf3d863e39e641ebf75fe203b', NULL, NULL, NULL, false, false, 'Oftalmología', 'Hombre de 67 años de edad, diabético y asmático, con un glaucoma primario de ángulo abierto en ambos ojos. Presenta una presión ocular de 34 mmHg en su ojo derecho y 31 mmHg en su ojo izquierdo.', '¿Cuál de los siguientes grupos farmacológicos es el más indicado como primera elección como tratamiento hipotensor?', '[{"position": 1, "text": "Inhibidores de la anhidrasa carbónica."}, {"position": 2, "text": "Beta-bloqueantes."}, {"position": 3, "text": "Agonistas alfa-2."}, {"position": 4, "text": "Derivados de prostaglandinas."}]'::jsonb, 4, 4, 'definitiva', 'Nos preguntan por el tratamiento de primera elección de un glaucoma. Antiguamente la primera elección eran los betabloqueantes, pero actualmente han sido desplazados por el grupo que más baja la presión intaocular: las prostaglandinas. Su eficacia y la posología más cómoda (una vez al día), los hacen en general el grupo de elección. Los betabloqueantes quedarían como segunda elección en casos en los que los efectos secundarios de las prostaglandinos (cambio de color de ojos, aumento del tamaño de las pestañas) nos hagan dejarlas inicialmente de lado. Debido a que el paciente es asmático, deberíamos descartar los betabloqueantes (respuesta 2 incorrecta). Además como necesitamos una bajada importante de presión intraocular porque las cifras son altas (34 y 31), podemos también descartar los inhibidores de la anhidrasa carbónica y los agonistas alfa-2 (opciones 1 y 3 incorrectas). Y decantarnos por el grupo que más puede bajar la presión intraocular. Respuesta 4 correcta. Y luego un par de matices del enunciado. Sería más correcto hablar de presión intraocular y no de “presión ocular”. Y la redacción podría mejorarse para no repetir la palabra “como” en la última frase.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a45e3dbf74b5', 'f66544ad4c6b86166f2f6b5aba240b4d2d2166a3', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 60 años, diabética insulinodependiente, que presenta omalgia derecha de predominio nocturno de varias semanas de evolución. No refiere traumatismo. En la exploración física destaca una limitación activa y pasiva de todos los arcos de movimiento del hombro.', '¿Qué cuadro clínico sospecha como primera posibilidad diagnóstica?', '[{"position": 1, "text": "Una tumoración maligna localizada en la epífisis proximal de húmero."}, {"position": 2, "text": "Una artritis séptica de hombro."}, {"position": 3, "text": "Una capsulitis adhesiva."}, {"position": 4, "text": "Un proceso degenerativo artrósico acromioclavicular."}]'::jsonb, 4, 3, 'definitiva', 'Todo apunta a una capsulitis adhesiva, como bien dices. La edad, el sexo, la clínica… lo de la DM…', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-78d1af046eaa', '340db968c5b1fe0f28aca58e1d318e0d7bfbf732', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Niña de 11 años y 6 meses, premenárquica, con escoliosis idiopática conocida. La radiografía de raquis realizada hace 6 meses mostraba una curva tórca-lumbar izquierda de 18º (ángulo de Cobb). En la actual se observa un ángulo de Cobb de 28º, con una maduración de cresta iliaca (signo de Risser) de 2.', 'En este momento evolutivo, ¿qué tratamiento es el más adecuado para intentar detener la progresión de la curva?:', '[{"position": 1, "text": "Ejercicios de natación."}, {"position": 2, "text": "Ejercicios de reeducación postural."}, {"position": 3, "text": "Corsé ortopédico corrector."}, {"position": 4, "text": "La intervención quirúrgica mediante artrodesis espinal."}]'::jsonb, 4, 3, 'definitiva', 'En las formas juvenil y del adolescente el tratamiento depende de los grados de deformidad: • 10 – 20°: observación seriada. • 20-50°: corsés de termoplástico (Boston, Cheneau o Milwaukee, según dónde se localice el ápex de la curva principal). • 40-50°: con Risser menor de 3 estaría indicada la artrodesis quirúrgica; con Risser mayor o igual de 3 el potencial remanente de crecimiento de la curva es escaso y se puede valorar la observación por si tendiera a progresar en la edad adulta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-76cb0d064eef', '0bda1ebd209f8896df50a830fd09964521fe8298', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer que presenta dificultad para caminar tras una cirugía ginecológica. Tiene dolor leve en el muslo y le falla la pierna al apoyar. En la exploración presenta debilidad para la flexión de la cadera y para la extensión de la rodilla, y disestesias en la cara anterior del muslo.', '¿Cuál es el diagnóstico de sospecha más probable?:', '[{"position": 1, "text": "Neuropatía del nervio femoral."}, {"position": 2, "text": "Meralgia parestésica del nervio fémoro cutáneo."}, {"position": 3, "text": "Neuropatía del nervio obturador."}, {"position": 4, "text": "Neuropatía del nervio ciático."}]'::jsonb, 4, 1, 'definitiva', 'El nervio femoral (aunque poco habitual) puede ser dañado en una operación cesárea, una histerectomía o una operación abdominal baja. Esta lesión nerviosa produce hipoestesia y debilidad a lo largo de su distribución. La femoroneuropatía se manifiesta por una parálisis (25% de los casos) de los músculos cuádriceps, abolición de los reflejos rotulianos e hipoestesia de la cara anterior e interna del muslo. Por lo tanto, respuesta 1 correcta. El nervio fémoro cutáneo o cutáneo femoral lateral (L2,L3) es solo sensitivo encargándose de la sensibilidad de la piel de la cara lateral y anterior del muslo hasta la rodilla, por lo que no explicaría el problema motor de la marcha y 2 es falsa. El nervio obturador (L2-L4) es un nervio mixto. A nivel motor inverva el obturador externo, pectíneo, aproximador corto, los aproximadores (aductores) y grácil. A nivel sensitivo la cápsula de la articulación coxofemoral, cara medial del muslo por encima de la rodilla. Por tanto ni afecta a la sensibilidad de la cara anterior del muslo ni a la extensión de la rodilla de modo que 3 es falsa. Una lesión del nervio ciático a nivel motor afecta a la flexión de la rodilla no a su extensión y a nivel distal a esta (no cuentan nada de clínica distal) y a nivel sensitivo también es distal en la cara externa de la pierna y en el pie por lo que 4 también es falsa.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7a722f7f42c9', '6c939ecb95174bf9c0635dcd202d916f222437e3', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Un hombre de 18 años llega al servicio de urgencias del hospital trasladado por una unidad de soporte vital básico. Ha sido atropellado por un automóvil cuando iba en bicicleta. A su llegada tiene una frecuencia cardíaca de 115 lpm, una presión arterial de 110/75 mmHg, pulso radial palpable, un relleno capilar de 2,5 segundos y una frecuencia respiratoria de 25 rpm.', '¿Qué nos indican estos datos?:', '[{"position": 1, "text": "Ha perdido entre un 15 y un 30% de la volemia y precisa reposición de volumen."}, {"position": 2, "text": "Ha perdido más de un 30% de la volemia y precisa reposición de volumen y de sangre."}, {"position": 3, "text": "Ha perdido más de un 40% de la volemia y precisará tratamiento quirúrgico."}, {"position": 4, "text": "Ha perdido más de un 50% de la volemia y precisa reposición de volumen y de sangre."}]'::jsonb, 4, 1, 'definitiva', 'Técnicamente el paciente se encuentra en un grado II de hemorragia según la clasificación de la ATLS, en principio esto nos habla de una pérdida de entre 750 y 1500mL de sangre y la actuación indicada es reanimación con cristaloides; no obstante, en las guías de atención al paciente politraumatizado grave, cada vez se preconiza más el uso precoz de hemoderivados, sobre todo en casos límite como este, y en pacientes jóvenes, que pueden no llegar a traducir la gravedad de la pérdida sanguínea hasta que esta se hace mucho más significativa. Por tanto dudaría entre las opciones 1 y 2.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9ab667bb23aa', '6dd9ec41a69bbf1757e0d6b65203ca520224ee88', NULL, NULL, NULL, false, false, 'Pediatría', 'Niña de 5 años, completamente asintomática, y que acude a la revisión habitual del pediatra. Consulta porque su madre fue operada de un tumor de tiroides y una abuela falleció hace 10 años por un feocromocitoma.', 'La actitud terapéutica prioritaria que adoptaremos será:', '[{"position": 1, "text": "Exploración física exhaustiva con control de la tensión arterial para valorar si el niño puede presentar alguna enfermedad familiar."}, {"position": 2, "text": "Análisis bioquímico con calcitonina. Si ésta es normal no es preciso más control a esta edad."}, {"position": 3, "text": "Seguimiento anual de los niveles de calcitonina con estimulación con pentagastrina y, si se eleva, indicar una tiroidectomía profiláctica."}, {"position": 4, "text": "Estudio genético de la mutación del proto-oncogen RET c634, y si es positivo se realizará la tiroidectomía radical profiláctica a esta edad."}, {"position": 5, "text": "Estudio genético de la mutación proto-oncogen RET c634, niveles de calcitonina y PAAF (punción aspiración con aguja fina) y si son positivas se realizará la tiroidectomía radical."}]'::jsonb, 5, 4, 'definitiva', 'La respuesta correcta es la 4. Me parece una pregunta más de Endocrino que de Pediatría. Los portadores del protooncogen suelen tener tumoraciones tiroideas precoces por lo que se suele recomendar la tiroidectomía radical antes de los 5 años. Obviamente esto lo he tenido que buscar…no es muy frecuente en nuestra práctica habitual.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8aaebc81617c', '288254cf815c881b4d509271a8c9c1122ee82970', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Paciente diagnosticado de diverticulitis aguda, tratado con amoxicilina/clavulánico. Al cabo de 5 días comienza con fiebre y diarrea. Se le diagnostica de colitis por Clostridium difficile, se suspende la amoxicilina/clavulánico y se pauta metronidazol. A los 4 días no ha respondido al metronidazol, pero se encuentra clínicamente estable.', 'El siguiente paso del tratamiento es:', '[{"position": 1, "text": "Cambiar el metronidazol por vancomicina oral (125 mg, cuatro veces al día durante 10 días)."}, {"position": 2, "text": "Cambiar el metronidazol por piperacilina/ tazobactam (4 g de piperacilina/0,5 g de tazobactam cada 8 horas)."}, {"position": 3, "text": "Indicar una colectomía subtotal."}, {"position": 4, "text": "Realizar una ileostomía en asa con lavado anterógrado de polietilenglicol."}]'::jsonb, 4, 1, 'definitiva', 'El tratamiento de elección de la infección por Clostridioides difficile es la vancomicina vía oral 125mg/6h durante 10 días. El metronidazol ha quedado relegado a situaciones en las que no se dispone de vancomicina.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6e51944ef628', '8db8ceceba7b0e7e3ea20b521c5e398af517e79d', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Un paciente de 36 años, oriundo de otra cultura que vive en España desde hace 4 años se presenta en una consulta de S.N. de Salud. Refiere presentar desde hace 10 meses sintomatología ansiosa y humor depresivo. Este cuadro interfiere moderadamente en su actividad cotidiana. No tiene antecedentes psiquiátricos previos. Dicha situación se produce a raíz del fallecimiento, en un accidente automovilístico, de un hermano mayor con quien se encontraba muy unido.', 'Señalar cuál de los siguientes diagnósticos es el apropiado:', '[{"position": 1, "text": "Depresión mayor."}, {"position": 2, "text": "Trastorno bipolar II."}, {"position": 3, "text": "Trastorno de adaptación."}, {"position": 4, "text": "Distimia."}, {"position": 5, "text": "Ciclotimia."}]'::jsonb, 5, 3, 'definitiva', 'La relativa levedad de los síntomas, que no interfieren de forma grave en su actividad diaria, excluye en principio el diagnóstico de depresión mayor. No hay datos de fases hipomaníacas que justifiquen un trastorno bipolar II. La distimia precisa una duración de al menos dos años. La ciclotimia es un diagnóstico hoy en día muy raro (porque, como decía Castilla del Pino en una entrevista, lo que antes eran ciclotímicos los llamamos ahora bipolares, contribuyendo a una de las múltiples epidemias psiquiátricas de nuestro tiempo), que consta de oscilaciones entre el polo depresivo y el maniforme, leves. Pero no hay datos de tales oscilaciones. La respuesta correcta es, con toda probabilidad, la 3. El trastorno adaptativo aparece en los 3 meses posteriores al acontecimiento estresante y no dura más de 6 meses si ha cesado el mismo o sus consecuencias (lo que no es el caso porque el hermano del imaginario paciente sigue muerto). Los síntomas ansioso-depresivos leves encajan con tal diagnóstico. Una muestra más de cómo conceptualizar como enfermedad lo que son hechos (aunque dolorosos) de la vida. Seguro que el imaginario paciente se lleva algún antidepresivo porque a lo mejor algo ayuda (1).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-406d03e748cc', 'c2f97a91a503d2d1041e7b7d9255ac872bc933fb', NULL, NULL, NULL, false, false, 'Oncología', NULL, 'Ante un paciente que presenta una lesión úlcerovegetante en la encía mandibular a nivel de la región de los molares de 5 meses de evolución, la aparición de hipoestesia en la región mentoniana requiere descartar:', '[{"position": 1, "text": "Una neuropatía paraneoplásica."}, {"position": 2, "text": "El diagnóstico de sarcoidosis con parálisis facial «en báscula»."}, {"position": 3, "text": "Infección por virus herpes en paciente inmunodeprimido."}, {"position": 4, "text": "El diagnóstico de carcinoma con infiltración del canal mandibular."}]'::jsonb, 4, 4, 'definitiva', 'Las parestesias mentonianas (signo de Roger) se asocian a metástasis óseas (no es paraneoplásico sino infiltración directa). En este caso lo que describen es un tumor oral creciendo localmente e infiltrando el canal mandibular, creo.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-60098f06ba99', '9958f4eb8bc3be8185eb2a221be1e88c9a7c11c3', NULL, NULL, NULL, false, false, 'Endocrinología', 'Mujer de 55 años con diabetes tipo 1 diagnosticada a los 15 años que refiere náuseas y distensión abdominal, especialmente después de las comidas. La evaluación es compatible con una gastroparesia diabética.', '¿Cuál de los siguientes medicamentos sería el tratamiento más adecuado para mejorar sus síntomas?:', '[{"position": 1, "text": "Lansoprazol."}, {"position": 2, "text": "Ondansetrón."}, {"position": 3, "text": "Loperamida."}, {"position": 4, "text": "Metoclopramida."}]'::jsonb, 4, 4, 'definitiva', 'Fue aprobada como tratamiento para la gastroparesia por la Food and Drug Administration (FDA) de los Estados Unidos en 1979 y sigue siendo el fármaco de primera línea. Actúa como procinético por su efecto antagónico sobre la dopamina 2 de los receptores (D2) promoviendo el vaciamiento gástrico y, además, se une al receptor 5-hidroxitriptamina 4 (serotonina 5-HT4) para estimular las vías nerviosas colinérgicas en el estómago. Fisiológicamente, acelera el tránsito intestinal al aumentar el tono y la amplitud de las contracciones gástricas, incrementa la presión del esfínter esofágico inferior y mejora la coordinación antropiloroduodenal. Además, este agente antiemético proporciona alivio a través del antagonismo de receptores centrales y periféricos de la dopamina.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-013d93b25111', '203cc841b6a59a28e7f3d140a26dd18a2775ad01', NULL, NULL, NULL, false, false, 'Nefrología', 'Mujer de 67 años con enfermedad renal crónica secundaria a nefropatía diabética. En la actualidad presenta una creatinina de 3,2 mg/dl con filtrado glomerular estimado (CKD-EPI) 14 ml/min.', '¿Cuál de las siguientes afirmaciones es cierta?:', '[{"position": 1, "text": "Presenta una enfermedad renal crónica estadio 3 y debe iniciar quelantes del fósforo."}, {"position": 2, "text": "Presenta una enfermedad renal crónica estadio 5 y debe considerarse el tratamiento renal sustitutivo."}, {"position": 3, "text": "Un buen control glucémico puede revertir la insuficiencia renal."}, {"position": 4, "text": "Es poco probable que presente una proteinuria superior a 500 mg/24 h."}]'::jsonb, 4, 2, 'definitiva', 'Un filtrado glomerular inferior a 15 ml/min se clasifica como estadio 5 (G5), indicando que la enfermedad renal se encuentra en estadio terminal y debe plantearse el inicio de terapia sustitutiva (opción 2 cierta, opción 1 falsa). En esta situación no es esperable que un buen control glucémico pueda revertir el daño renal, aunque sí podría ayudar a retrasar la progresión (opción 3 falsa). Estos pacientes suelen presentar una albuminuria estadio A3 (superior a 300 mg/24 h), pudiendo llegar al rango nefrótico (opción 4 falsa).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0fc6e09e5b92', 'defcf5577787fe520970db89a61429086c8f246a', NULL, NULL, NULL, false, false, 'Nefrología', 'Mujer de 75 años en tratamiento con sertralina que acude a urgencias por un cuadro confusional. No se evidencian edemas y la tensión arterial es de 130/70. En la analítica destaca Na 126 mEq/l y K 4 mEq/l, la natriuria es de 45 mEq/l y se ha descartado la ingesta de diuréticos.', '¿De las siguientes cuál es la actitud más correcta?:', '[{"position": 1, "text": "Se trata de una enfermedad de Addison y deben administrarse corticoides de inmediato."}, {"position": 2, "text": "Administrar suero salino hipertónico a fin de restablecer cuanto antes la natremia."}, {"position": 3, "text": "Indicar restricción hídrica y si no se eleva la natremia pasar a infusión lenta de suero salino."}, {"position": 4, "text": "Solicitar resonancia magnética cerebral, ya que seguramente se trata de una diabetes insípida."}]'::jsonb, 4, 3, 'definitiva', 'Nos presentan a una paciente con una hiponatremia moderada euvolémica, orientando hacia un síndrome de antidiuresis inadecuada (SIAD) secundario a la sertralina, aunque sería necesario disponer de la osmolalidad urinaria para confirmarlo. La insuficiencia suprarrenal primaria produce hiponatremia hipovolémica (opción 1 incorrecta). La diabetes insípida es la contraposición a esta patología, presentándose habitualmente con hipernatremia (opción 4 incorrecta). La duda queda entre si hay que tratar de forma agresiva con suero salino hipertónico, o ser más conservador indicando restricción hídrica. Con natremias superiores a 125 mmol/l no está indicado tratar con SSH salvo que el paciente tenga clínica neurológica grave, que no parece el caso (describen un cuadro confusional que sería una encefalopatía hiponatrémica moderada), y tampoco está indicado restablecer cuanto antes la natremia (por el riesgo de síndrome de desmielinización osmótica). Por tanto, la respuesta correcta sería la 3. Lo que no me gusta de esa respuesta es que la segunda parte (“si no se eleva la natremia pasar a infusión lenta de suero salino”) es incorrecta, ya que en ese caso habría que plantearse el uso de furosemida, tolvaptan o urea, no suero salino (y tampoco indica la tonicidad, no es lo mismo un isotónico que un hipertónico). En cualquier caso, no la veo muy susceptible de anularse.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4a66c55d8d8f', '1af1c6867f1d9856e615ce665fdcf46f4138f681', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Varón de 30 años que consulta por cefaleas perioculares unilaterales que progresan rápidamente hasta hacerse muy intensas. Las crisis de dolor duran entre 30-60 minutos, ocurren 2-3 veces al día y se acompañan de lagrimeo en el ojo que le duele y rinorrea unilateral.', '¿Cuál es el tratamiento preventivo más adecuado?:', '[{"position": 1, "text": "Prednisona oral con retirada en 2-3 meses."}, {"position": 2, "text": "Prednisona oral con retirada en un mes, asociada a verapamilo oral a dosis de 80-180 mg cada 8 horas."}, {"position": 3, "text": "Carbamazepina a dosis de 600-1200 mg al día."}, {"position": 4, "text": "Indometacina a dosis de 50 mg cada 8 horas durante un mes."}]'::jsonb, 4, 2, 'definitiva', 'Describen un caso característico de cefalea en racimos. Es más frecuente en varones, el dolor es característicamente periocular unilateral de gran intensidad, de duración variable, generalmente minutos y asocia signos trigeminoautonómicos como la rinorrea e inyección conjuntival unilateral. El tratamiento preventivo por excelencia es el verapamilo asociado a pauta descendente de corticoides, tal y como se expone en la respuesta 2.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f20fc8185f81', '744e155712e8d40f8f2113699d4bc876bc7dc69b', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Varón de 45 años traído a la consulta por sus familiares por un cuadro de un año de evolución de pérdida de memoria, que ha ido progresando hasta necesitar ayuda para algunas actividades de su vida cotidiana. Tiene antecedentes de migrañas y algún episodio de focalidad neurológica autolimitada por los que no ha consultado nunca. La exploración neuropsicológica es compatible con una demencia inicial y la RM cerebral muestra una leucoencefalopatía grave.', '¿Qué prueba habría que solicitar?:', '[{"position": 1, "text": "Punción lumbar para analizar amiloide y proteína tau en LCR."}, {"position": 2, "text": "Estudio genético para presenilina 1 (PSEN1)."}, {"position": 3, "text": "Estudio genético para NOTCH3."}, {"position": 4, "text": "Estudio genético para progranulina."}]'::jsonb, 4, 3, 'definitiva', 'Describen un caso característico de CADASIL (Cerebral Autosomal Dominant Arteriopathy with Sub-cortical Infarcts and Leukoencephalopathy). Es una enfermedad genética, de herencia autosómica dominante por mutación del gen NOTCH3. Esta mutación provoca afectación vascular de pequeño vaso que genera leucoencefalopatía grave de forma precoz, lo que genera sintomatología variada. Destacan las migrañas, la enfermedad cerebrovascular y deterioro cognitivo a edades tempranas, tal y como muestra el caso clínico de la pregunta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-de4b6ef8e385', 'ae71322c3d9274aa1ab40eb41f924475cd23f07c', NULL, NULL, NULL, false, false, 'Reumatología', 'Mujer de 26 años diagnosticada de lupus eritematoso sistémico, en tratamiento con hidroxicloroquina, que consulta por sensación de debilidad generalizada que se ha instaurado progresivamente en los últimos 15 días. En la exploración física se aprecia palidez cutánea y en la analítica destaca Hb 7,4 gr/dL, Hcto 31%, VCM 108.', '¿Cuál de las siguientes determinaciones será más útil para decidir la actuación?', '[{"position": 1, "text": "Haptoglobina."}, {"position": 2, "text": "Test de Coombs."}, {"position": 3, "text": "Vitamina B12."}, {"position": 4, "text": "Anticuerpos antinucleares."}]'::jsonb, 4, 2, 'definitiva', 'En esta pregunta, nos plantean una paciente con lupus eritematoso sistémico que presenta una anemia hemolítica autoinmune. Para ello, la mejor opción sería solicitar unos reticulocitos, no obstante, como no se encuentra entre las opciones, deberíamos solicitar un test de Coombs, por lo que la respuesta correcta es la 2. Si bien, nos quieren confundir con un VCM 108, para que pensemos en una anemia megalobástica, el VCM no es excesivamente elevado, la instauración de la anemia en nuestra paciente ha sido rápida y no cuadraría con el LES ni la forma de presentación. Los anticuerpos antinucleares se utilizan para el diagnóstico, pero no para el seguimiento del LES.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d35533d5efe1', '1fc3b392928fcb48ef646864e591ec91583ab957', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 13 años, sin antecedentes relevantes, con menarquia hace 3 meses, seguida desde los 10 años por escoliosis idiopática que ha empeorado.', 'En la exploración física presenta una giba de 7 grados en el test de Adams y en el escoliograma una curva toracolumbar T4-L1 de 35 grados de Cobb y un Risser 0.', '[{"position": 1, "text": "Recomendar natación y revisión en tres meses."}, {"position": 2, "text": "Prescribir una ortesis tipo corsé."}, {"position": 3, "text": "Derivar a fisioterapia para elastificación del raquis."}, {"position": 4, "text": "Revisar en 6 meses con una nueva radiografía."}]'::jsonb, 4, 2, 'definitiva', 'Nos presentan el caso de una paciente de 13 años, con la menarquia hace 3 meses, una curva toracolumbar T4-L1 de 35º y un Risser 0. Como norma general podríamos decir que por debajo de los 50º el tratamiento suele ser conservador, existiendo dos opciones: observación o uso de corsé para enlentecer la evolución. En este caso teniendo en cuenta el crecimiento remanente que queda (menarquia hace 3 meses y Risser 0) lo más indicado sería utilizar corsé (Respuesta 2 correcta).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-18aa065205ca', 'ef7065831ed39edc515211517b393dc58351fb41', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Un hombre de 30 años sufre caída de una altura de 2 metros de pie. A su llegada a Urgencias, está cyo, con sondaje vesical con orina clara. Muestra tumefacción de talón izquierdo, así como hormigueos leves por cara anterior de muslo derecho y escroto, así como disestesias en ambos pies. El paciente se despide del camillero con un apretón de manos, con una palmada simultánea en el hombro. La rotación de los MMII en la camilla cogidos por los tobillos es indolora y la compresión de la pelvis es asintomática.', 'A continuación:', '[{"position": 1, "text": "Lo sentaremos en la camilla para poder explorar la columna cervical."}, {"position": 2, "text": "Remitiremos a Rx para realizar estudio de extremidades inferiores."}, {"position": 3, "text": "Palparemos el abdomen y lo rotaremos en bloque para palpar la columna toraco-lumbar."}, {"position": 4, "text": "Le colocaremos un collarín cervical y remitiremos a radiología para estudio de imagen de columna cervical y extremidades inferiores."}, {"position": 5, "text": "Solicitaremos una eco abdominal."}]'::jsonb, 5, 3, 'definitiva', 'Por los síntomas que cuentan, hormigueo en cara anterior de muslo, escroto y disestesias en pies, parece existir una afectación vertebral a nivel L2-3 y raíces sacras, con lo que lo correcto sería realizar un examen radiológico sin estar movilizando al paciente. Pero sí hay que movilizarlo para explorarlo, evidentemente, en bloque. La columna cervical parece estar indemne porque el paciente moviliza adecuadamente los dos brazos, sin parestesias.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-92d09761ba12', 'ed0bffaeed29079ca806f4738b01a361f69e8bc9', NULL, NULL, NULL, false, false, 'Anatomía Patológica', 'Un hombre de 56 años, diabético y con sobrepeso moderado presenta una discreta hepatomegalia. El enfermo indica que no es bebedor habitual, sólo excepcionalmente toma algo de vino. Una biopsia de hígado muestra acúmulos de vacuolas claras citoplásmicas en un 50% de los hepatocitos. Focos inflamatorios múltiples con neutrófilos, degeneración hialina de Mallory y fibrosis alrededor de las vénulas hepáticas terminales.', 'Señale la respuesta correcta en este caso:', '[{"position": 1, "text": "Debe repetirse la biopsia para saber si los cambios son difusos."}, {"position": 2, "text": "El diagnóstico es una glucogenosis hepática asociada a la diabetes."}, {"position": 3, "text": "Los cambios histológicos son irreversibles y acabarán produciendo una cirrosis."}, {"position": 4, "text": "La lesión está causada claramente por el alcohol a pesar de la negativa del enfermo."}, {"position": 5, "text": "Es importante disminuir peso y controlar adecuadamente la diabetes para evitar el posible desarrollo de una cirrosis."}]'::jsonb, 5, 5, 'definitiva', 'Los cambios descritos en el enunciado de la pregunta corresponden a una situación precirrótica precoz. Si bien el alcohol es el tóxico que con más frecuencia provoca este cuadro, no es el causante en exclusiva. La diabetes mellitus provoca alteraciones hepáticas similares: acúmulo de grasa en los hepatocitos, fibrosis centroacinar, infiltrado inflamatorio por polimorfonucleares neutrófilos y degeneración hialina de mallory perinuclear. Teniendo esto en consideración, podemos descartar la segunda pregunta (son acúmulos de grasa intracelular, no de glucógeno) y la cuarta (si la diabetes también produce dicha situación no hay por qué desconfiar del paciente). Basándonos en el primum non nocere y el no tener especial relevancia para el tratamiento si es una enfermedad focal o generalizada, no es necesario repetir una biopsia hepática que no ampliaría información, descartándose la primera pregunta. Afortunadamente para el hipotético paciente, en fase inicial estos cambios son reversibles al desaparecer la noxa, por lo que nos quedamos con la respuesta nº 5.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5eb90283fb43', '5b1212b6bfd84d7fbd4d81a776769899681da1b4', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Una mujer de 67 años con antecedentes de insuficiencia cardiaca congestiva (que lleva tratamiento con ramipril y furosemida) y diabetes tipo 2 (en tratamiento con insulina) acue a urgencias por disnea. En gasometría realizada respirando aire ambiente se observa un pH 7.45, paO2 56, PaCO2 30 mm Hg, HCO3 26 mm Hg.', '¿Qué alteración gasométrica presenta la paciente?', '[{"position": 1, "text": "Insuficiencia respiratoria hipoxémica con alcalosis respiratoria compensada."}, {"position": 2, "text": "Alcalosis metabólica aguda con insuficiencia respiratoria hipoxémica e hipocápnica."}, {"position": 3, "text": "Insuficiencia respiratoria normocapnica crónica, sin alteración del equilibrio acido-base."}, {"position": 4, "text": "Insuficiencia respiratoria hipoxémica crónica con acidosis metabólica compensada."}, {"position": 5, "text": "Insuficiencia respiratoria hipoxémica con alcalosis mixta compensada."}]'::jsonb, 5, 1, 'definitiva', 'Esta pregunta me ha parecido complicadilla. Los hallazgos por separado son: pH normal pero con tendencia alcalosis, Insuficencia respiratoria aguda, hipocapnia y bicarbonato normal. La respuesta mas apropiada me parece la 1, dado que la paciente no presenta una alcalosis metabólica (el bicarbonato estaría mas elevado), mucho menos una acidosis (el bicarbonato estaría bajo). La alcalosis tampoco es mixta, sino que es principalmente respiratoria. Probablemente la paciente esté hiperventilando por su insuficiencia respiratoria, y el riñón que siempre compensa mas tarde está empezando a retener HCO3 para compensar y mantener el pH. Por tanto creo que la respuesta correcta es la 1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-240e2e470248', '5b4882fae1c3b793b8ecf7de038c3279fabd979a', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Mujer de 76 años con obesidad y diabetes mellitas tipo 2 en tratamiento con metformina. Acude a urgencias porque desde hace 3 días presenta fiebre de 38ºC, poliaquiuria, disuria, intensa sed y disminución progresiva del nivel de consciencia. En la exploración física se aprecian signos de deshidratación, PA de 95/54 mm Hg y no hay signos de localidad neurológica. En la analítica destaca leucocitosis, creatinina de 1,8 mg/dL y glucemia de 855 mg/dL.', '¿Cuál es el diagnóstico mas probable?', '[{"position": 1, "text": "Coma hiperglucémico hiperosmolar no cetósico."}, {"position": 2, "text": "Insuficiencia cardiaca."}, {"position": 3, "text": "Hematoma subdural."}, {"position": 4, "text": "Insuficiencia renal de causa obstructiva."}, {"position": 5, "text": "Cetoacidosis diabética con coma."}]'::jsonb, 5, 1, 'definitiva', 'La pregunta cuenta el caso de una paciente diabética tipo 2 con hiperglucemia y disminución del nivel de conciencia sin focalidad neurológica en el contexto de una infección urinaria y que ha desarrollado una insuficiencia renal aguda de probable origen prerrenal. La opción 2 se descarta de forma inmediata puesto que el cuadro clínico no es de insuficiencia cardiaca. La opción 3 también se descarta porque no cuadra con la clínica y además el HSD daría clínica neurológica con localidad. La opción 4 se descarta puesto que la insuficiencia renal obstructiva no da poliaquiuria, disuria ni el resto de la clínica. La opción 5 es menos probable porque la cetoacidosis diabética es mas tipica de DM tipo 1. Por tanto la opción correcta es la 1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-872b5f7dca5e', '98a2e918806b0c0f6351d98baf36ddcb9dffb319', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Un paciente de 81 años consulta por un episodio de síncope. Refiere disnea de esfuerzo desde hace un año. En la auscultación cardiaca destaca un soplo sistólico 3/6 en borde esternal izquierdo que irradia a carótidas y punta.', '¿Qué patología le parece más probable?', '[{"position": 1, "text": "Bloqueo aurículo-ventricular de tercer grado."}, {"position": 2, "text": "Estenosis valvular aórtica degenerativa."}, {"position": 3, "text": "Insuficiencia valvular mitral."}, {"position": 4, "text": "Miocardiopatía hipertrófica."}, {"position": 5, "text": "Miocardiopatía dilatada."}]'::jsonb, 5, 2, 'definitiva', 'Pregunta muy fácil. Nos están describiendo el “retrato” de una estenosis aórtica degenerativa… Paciente anciano con clínica de disnea y síncope, y soplo sistólico irradiado a carótidas y punta, todo ello típico de esta enfermedad.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-626abc133652', 'c98242cbe31136fddcce84bf7b9e74fecce328f4', NULL, NULL, NULL, false, false, 'Cirugía General', 'Mujer de 26 años que presenta incontinencia fecal después de un parto prolongado e instrumental. Se practica ecografía endoanal apreciándose una sección del esfínter anal externo de 30º de amplitud. El estudio electrofisiológico demuestra una inervación normal.', '¿Cuál es el tratamiento más indicado?', '[{"position": 1, "text": "Tratamiento médico con normas higiénicodietéticas."}, {"position": 2, "text": "Biofeedback esfinteriano."}, {"position": 3, "text": "Esfinteroplastia quirúrgica."}, {"position": 4, "text": "Reparación quirúrgica del suelo pélvico."}, {"position": 5, "text": "Esfínter anal artificial."}]'::jsonb, 5, 3, 'definitiva', 'La respuesta es la 3 esfinteroplastia quirúrgica. La 1 no es eficaz, la 2 tampoco para una lesión orgánica con electromiografía normal, la 4 no es necesaria ya que la lesión es sólo del esfínter externo, la 5 no está indicada en una lesión que se puede reparar con cirugía con buenos resultados.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9a74909f4c20', '9c195f9db7294a097acfbcb6b30d3b907ce2cec5', NULL, NULL, NULL, false, false, 'Genética e Inmunología', 'Niño de 2 años. En sus antecedentes personales destacan: 3 episodios de otitis media aguda, 1 meningitis meningocócica y 2 neumonías (una de lóbulo medio y otra de lóbulo superior izquierdo). Ha ingresado en 3 ocasiones por púrpura trombopénica (en tres ocasiones los anticuerpos antiplaquetas fueron negativos y en la médula óseas se observaban megacariocitos normales). Varios varones de la familia materna habían fallecido en la infancia por procesos infecciosos. En la exploración física presenta lesiones típicas de dermatitis atópica. En el estudio inmunológico destaca una leve disminución de subpoblaciones de linfocitos T; elevación de IgA e IgE; disminución de IgM y IgG en el límite inferior de la normalidad.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Síndrome de Wiskott-Aldrich."}, {"position": 2, "text": "Síndrome de hiper IgE."}, {"position": 3, "text": "Hipogammaglobulinemia transitoria de la infancia."}, {"position": 4, "text": "Inmunodeficiencia combinada severa ligada al X."}, {"position": 5, "text": "Inmunodeficiencia variable común."}]'::jsonb, 5, 4, 'definitiva', 'Para contestar correctamente a esta pregunta hay que resaltar que de entre la sintomatología que se expone se encuentran: • Niño de 2 años. • Infecciones ORL. • Infecciones Pulmonares. • Ingresos Hospitalarios. • PTI. • Historia Familiar de infecciones con muertes por infecciones en Varones (familia materna). • Dermatitis Atópica. Todos estos datos, en conjunto, además de los analíticos, están describiendo una inmunodeficiencia que por la historia familiar-materna, parece ligada al X, al ser varios los varones fallecidos por una clínica similar (el padre del paciente aportó el cromosoma Y, la madre el X). Dentro de las inmunodeficiencias ligadas al X se encuentra el Síndrome de Wiskott-Aldrich, una entidad que se describe con una tríada inicial de síntomas consistentes en sangrado (típicos AUNQUE ausentes en el caso: sangrado abundante tras la realización de circuncisión, diarrea sanguinolienta), infecciones de repetición y eczema. Además de la trombocitopenia presentan un riesgo incrementado para padecer fenómenos autoinmunes y neoplasias linfoides. A la opción de Hiper-IgE le faltan datos clínicos muy característicos como las alteraciones óseas y las lesiones cutáneas, que no son de dermatitis atópica, ya que siguen un patrón diferente (erupción pápulopustular en la cara y el cuero cabelludo. A la opción de Hipogammaglobulinemia transitoria de la infancia y las inmunodeficiencias combinada severa y variable común les falla, entre otras características, la determinación de inmunoglobulinas G y M, que están en el límite inferior, pero dentro de la normalidad.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d7a629b20512', 'b2daf56b0ed00a8f10f3c3962dd113383696f5ca', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Paciente de 67 años con antecedente de menopausia a los 55 años, 3 gestaciones con 3 partos eutócicos, diabetis tipo 2 de 6 años de evolución, tratamiento con nifedipono por HTA. Consulta por cuadro de metrorràgia escassa intermitente de 2 meses de evolución. En la exploración ginecológica se aprecian unos genitales externos sin lesiones, un cérvix de aspecto atrófico, un útero y anejos normales a la palpación y un estudio citológico de cérvix normal. En el estudio ecográfico transvaginal se aprecia un endometrio hiperecogénico de 7mm.', '¿Cuál de las siguientes pruebas es la más indicada y con mayor sensibilidad para establecer un diagnostico?', '[{"position": 1, "text": "Conización de cèrvix."}, {"position": 2, "text": "Citología endometrial."}, {"position": 3, "text": "Histeroscopia y biopsia de endometrio."}, {"position": 4, "text": "Resonancia nuclear magnética de pelvis."}, {"position": 5, "text": "Exploración bajo anestesia de aparato genital y biòpsia de cérvix y endometrio."}]'::jsonb, 5, 3, 'definitiva', 'La respuesta correcta es la 3. El estudio que nos aporta mayor información sobre la patología endometrial es la histeroscopia, que nos permite realizar una biopsia dirigida de endometrio. La citologia endometrial se realiza a ciegas y tiene gran cantidad de falsos negativos. La resonancia nos ayudará a estadiar un cáncer de endometrio.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f04a0890a301', '312086739bdaa0fe62c26e4aad6fd39e77388d7e', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 32 años con parálisis cerebral del parto que acude a Urgencias por cuadro de orinas oscuras de unos días de evolución en relación con episodio de fiebre alta y tos seca. Al ingreso se objetiva en hemograma 16900 leucocitos/mm3 (85% S, 11% L, 4% M), hemoglobina de 6.3 gr/dl; VCM 109 fl, 360000 plaquetas/mm3. En la bioquímica LDH 2408; bilirrubina 6.8 mg/dl, (bilirrubina no conjugada 6.1 mg/dl), GOT y GPT normales. En el estudio morfológico de sangre se observa anisocitosis macrocítica con frecuentes formas esferocitadas y policromatofilia sin blastos. El estudio de anticuerpos irregulares es positivo en forma de panaglutinina, dificultando la prueba cruzada.', '¿Cuál sería su sospecha y el tratamiento más adecuado?', '[{"position": 1, "text": "Aplasia medular e inmunoterapia con timoglobulina y ciclosporina."}, {"position": 2, "text": "Esferocitosis hereditaria y esplenectomía."}, {"position": 3, "text": "Anemia hemolítica autoinmune asociada a infección respiratoria y corticoides."}, {"position": 4, "text": "Anemia perniciosa e inyecciones periódicas de vitamina B12."}, {"position": 5, "text": "Leucemia aguda y quimioterapia."}]'::jsonb, 5, 3, 'definitiva', 'Un enunciado largo lleno de datos bastante liosos. Podemos atacar esa pregunta de dos maneras: fijándonos en los datos claves y yendo del tirón al diagnóstico que consideramos o descartando una por una. La coluria, la LDH, la presencia de panaglutinina y el estudio del frotis de sangre periférica «huelen» a anemia hemolítica. La respuesta 1 no puede ser porque una aplasia medular no explica la coluria, la elevación de LDH, ni en el estudio de anticuerpos irregulares es positivo en forma de panaglutinina; una aplasia es una insuficiencia medular que se caracteriza por una desaparición total o parcial de progenitores hemopoyéticos. Además, no se observa una pancitopenia, que es lo que nos inclinaría más por esta patología. La respuesta 2 tampoco es posible, ya que una esferocitosis no justifica la presencia de panaglutinina. La respuesta 3 es la que considero correcta: una anemia hemolítica autoinmune sí justificaría los datos que nos dan: elevación de LDH y bilirrubinemia por destrucción de los hematíes, policromatofilia, esferocitosis y anisocitosis porque la médula está trabajando a marchas forzadas para intentar compensar la anemia, que es regenerativa. El estudio de anticuerpos irregulares y la presencia de panaglutinina también es un dato a favor de esta respuesta, ya que al unirse un anticuerpo al hematíe propicia su lisis y destrucción. La chica presenta tos y fiebre, lo que concuerda con una infección respiratoria. Y el tratamiento inicial son los corticoides. Lo confirma Sans Sabrafens en su libro «Hematología clínica» [1]. La respuesta 4 da lugar a bastantes dudas; no es posible porque una anemia perniciosa no justifica la presencia de panaglutinina aunque sí justificaría la elevación de LDH y bilirrubina; además, es una hemólisis intramedular, arregenerativa, no hay reticulocitosis ni lanzamiento a la sangre de formas inmaduras en un intento de compensar y arreglar la situación. La respuesta 5 no es cierta porque no se observan blastos en sangre ni explica la presencia de panaglutinina.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c2e8d4056c6d', '290b7177d934058cba26e8cf8b15f0666d23ff71', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 25 años de edad que desea quedarse embarazada y quiere saber qué tratamiento debe realizar durante el eventual embarazo, ya que es portadora del factor V Leiden en heterocigosis. Nunca ha tenido ningún fenómeno trombótico. Se realizó la determinación del mencionado factor como estudio familiar tras un episodio de embolia de pulmón en un hermano.', '¿Qué tratamiento se debe aconsejar?', '[{"position": 1, "text": "Dado que la gestación es un estado protrombótico, existiría un alto riesgo de tromboembolia venosa, por lo que se debe desaconsejar el embarazo."}, {"position": 2, "text": "Se debe realizar tratamiento con heparina de bajo peso molecular a dosis profilácticas en el puerperio inmediato, siendo opcional realizar igualmente seguimiento durante el embarazo."}, {"position": 3, "text": "El factor V Leiden en heterocigosis es una trombofilia de bajo riesgo y no hay necesidad de ningún tratamiento en el embarazo y puerperio."}, {"position": 4, "text": "Se debe aconsejar aspirina a bajas dosis durante embarazo y puerperio."}, {"position": 5, "text": "Se debe realizar tratamiento con fármacos antivitamina K (acenocumarol) durante el embarazo."}]'::jsonb, 5, 3, 'definitiva', 'Al leer las respuestas, lo primero que tenemos claro es que NO se debe administrar acenocumarol a una mujer embarazada por riesgo de teratogenicidad. Al que lo haga durante la residencia se le debe castigar con 100 fonendazos en la espalda. Descartamos respuesta 5. Lo segundo: si se pone tratamiento, debe ser durante todo el embarazo, el status protrombótico no es sólo durante el puerperio, así que respuesta 2 descartada. ¿Aconsejar a una mujer que no se quede embarazada habiendo tratamientos que aseguren un bajísimo riesgo de trombosis y/o afectación fetal? Respuesta 1 descartada. Nos quedamos con la posibilidad de no dar ningún tratamiento por ser de bajo riesgo o administrar aspirina a bajas dosis. Es cierto que el factor V Leiden en heterocigosis se cataloga como de bajo riesgo, que no ha presentado episodio trombótico previo ni hay combinación con otra trombofilia; si miramos la guía CHEST, VIII edición y repasam0s lo que se dijo en el último congreso de la Sociedad Española de Ginecología y Obstetricia, vemos que la aspirina se emplea en caso de síndrome fosfolípido y que en el caso de esta mujer, sin trombosis previa, sin abortos previos (se necesitan al menos dos) y además siendo heterocigota, no es necesario el tratamiento. Respuesta correcta, la 3.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-276a07c6acf2', 'eebd88499e62dcddd50a116d90ee76a9ed9495d8', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un varón de 64 años consulta por fiebre, tos, disnea y dolor pleurítico derecho de 1 semana de evolución. En la Rx de tórax se aprecia un derrame pleural derecho loculado que ocupa dos terceras partes del hemitórax. Durante la toracocentesis se extrae un líquido amarillento cuyo análisis muestra: leucocitos 15,000/uL, 92% de neutrófilos, glucosa 30 mg/dl, pH 7, lactato deshidrogenasa 3500 U/L, adenosina desaminasa 45 U/L y ausencia de gérmenes en la tinción de GRAM.', '¿Cuál es la siguiente acción más apropiada en este paciente?', '[{"position": 1, "text": "Antibioticoterapia intravenosa."}, {"position": 2, "text": "Antibioticoterapia intravenosa y repetir la toracocentesis diagnóstica en 24 horas."}, {"position": 3, "text": "Antibioticoterapia intravenosa y repetir la toracocentesis diagnóstica si no hay mejoría en 48 horas."}, {"position": 4, "text": "Antibioticoterapia intravenosa y realizar una toracocentesis evacuadora (terapéutica) si se aísla algún gérmen en el cultivo del líquido pleural."}, {"position": 5, "text": "Antibioticoterapia intravenosa y colocar un tubo o catéter torácico para drenar todo el líquido pleural."}]'::jsonb, 5, 5, 'definitiva', 'En esta pregunta no debe haber tampoco mucha duda (por cierto, que creo que es más de Neumología que mía, pero bueno, con esto de la fiebre mi amigo Emilienko se ha desviado), puesto que la clínica orienta a un Derrame pleural paraneumónico, las características macroscópicas del líquido así lo parecen y el análisis del mismo nos muestra que además el derrame está complicado, casi a pique de ser un empiema (LDH altísima, celularidad con predominio de PMN, consumo de glucosa). Con ese pH además, (y sabiendo que el derrame ya está loculado) el tubo endotorácico está más que indicado.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0aa4453dffd2', '4e62963f96e92339b253fbe45ae6e55e43695812', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Gestante de 27 años, 30 semanas de gestación. Acude a Urgencias por notar desde ayer dolor en región lumbar izquierda y disuria. No tiene sensación febril. Refiere infecciones del tracto urinario (ITU) reiteradas. En el análisis de orina se observan Hb 3+, leucocitos 3+, nitritos 2+, Sedimento: 15-20 leucocitos por campo y 5-10 hematíes por campo.', '¿Cuál de los siguientes microorganismos es el responsable más frecuente en las gestantes?', '[{"position": 1, "text": "Escherichia coli."}, {"position": 2, "text": "Enterococcus faecalis."}, {"position": 3, "text": "Streptococcus agalactiae."}, {"position": 4, "text": "Proteus mirabilis."}, {"position": 5, "text": "Satphylococcus saprophyticus."}]'::jsonb, 5, 1, 'definitiva', 'La respuesta correcta es la primera. La causa más frecuente de infecciones urinarias es Escherichia coli y en el caso de las embarazadas también.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c8e9e8242a84', '87a2db27e4652c6a3d76b26cf3bbf15071e42a4b', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un paciente de 32 años, diabético en tratamiento con insulina y un buen control de sus cifras de glucemia, acude a su consulta por presentar hormigueo en ambas manos, con sensación de acorchamiento e insensibilidad térmica de instauración progresiva en el curso de 2 semanas. No refiere trastornos visuales, déficit de fuerza, torpeza motora, ni otros síntomas. En la exploración encuentra una anestesia para el dolor y la temperatura en ambas manos y porción distal de antebrazos; la sensibilidad posicional y la vibratoria están conservadas. No presenta atrofia muscular ni déficit de fuerza. Los reflejos musculares son normales y simétricos. No se observa dismetría, disdiadococinesia ni temblor intencional. El resto de la exploración neurológica es rigurosamiente normal.', 'Indique cuál es el diagnóstico más probable en este caso:', '[{"position": 1, "text": "Neuropatía periférica sensitvo simétrica distal de causa diabética."}, {"position": 2, "text": "Lesión compresiva medular cervical."}, {"position": 3, "text": "Síndrome del túnel del carpo bilateral."}, {"position": 4, "text": "Enfermedad desmielinizante tipo esclerosis múltiple."}, {"position": 5, "text": "Lesión medular central cervical."}]'::jsonb, 5, 5, 'definitiva', 'La pregunta puñetera de la sección de Neurología de este año. Presenta un paciente diabético pero a tratamiento insulínico con buen control (aunque las neuropatías diabéticas no sólo se desarrollan en pacientes con mal control) con un cuadro sensitivo limitado a miembros superiores y de corto tiempo de instauración, sin clínica motora ni a otro nivel. En la exploración hay una clara disociación con anestesia termoalgésica y conservación de artrocinética y vibratoria. Los reflejos son normales, ni abolidos ni exaltados. Y además el resto de exploración es rigurosamente normal. Con todo ello creo que la respuesta correcta es la 5, o sea una lesión siringomiélica, cuya característica inicial es la disociación sensitiva con anestesia para la termoalgésica y conservación de la cordonal posterior. La EM y resto de lesiones medulares se acompañarían de otros signos exploratorios como exaltación de los reflejos, para el túnel carpiano la exploración excede el territorio distal al carpo, y en cuanto a la respuesta 1, si bien existen formas de polineuropatía periférica “pseudosiringomiélicas” suelen ser de inicio lumbar. El tiempo de evolución tan corto (2 semanas), el respeto de miembros inferiores y la conservación de los reflejos musculares hacen que descarte esta respuesta a pesar de que la distribución sea “en guante”.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4271237edfa7', 'a7512c56f71fc3a9b69d03b5fa567f98a8730a29', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Paciente mujer de 18 años, con hisotria de ausencias entre los 6 y 9 años, crisis tónico-clónicas generalizadas de reciente comienzo y saltos violentos de miembros superiores al desayunar. La clínica empeora con salidas nocturnas de fines de semana. Un EEG muestra descargar de polipuntas agudas a 6 ciclos/segundo.', 'El diagnóstico más probable es:', '[{"position": 1, "text": "Gran mal epiléptico."}, {"position": 2, "text": "Síndrome de Lennox-Gastaut."}, {"position": 3, "text": "Epilepsia sintomática por esclerosis temporal mesial."}, {"position": 4, "text": "Pequeño mal atípico."}, {"position": 5, "text": "Epilepsia mioclónica juvenil."}]'::jsonb, 5, 5, 'definitiva', 'Paciente en edad adolescente con mioclonías (“saltos violentos”) a la hora del desayuno, va a guiarnos casi siempre hacia la Epilepsia mioclónica juvenil (respuesta 5 correcta), entidad muy bien caracterizada. Entre otras características está la historia previa de crisis o ausencias, el empeoramiento con las salidas nocturnas, y el EEG con descargas de polipuntas generalizadas a una frecuencia mayor que el de las ausencias. Del resto de respuestas, el Lennox Gastaut se desarrolla a una edad temprana con otra sintomatología, la 4 es lo mismo que ausencias, y la 3 suele cursar con crisis parciales complejas y de cualquier manera, el EEG es claramente distinto a un foco temporal.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-30093cc37d91', '40ba1c311e1681b247ae73b4611563df04493f43', NULL, NULL, NULL, false, false, 'Oftalmología', 'Mujer de 75 años diagnosticada hace 3 años de drusas blandas en el fondo de ojo. Refiere presentar, desde hace 2 semanas, metamorfopsia y pérdida visual importante en su ojo derecho que le impide leer.', 'Señale el diagnóstico más probable:', '[{"position": 1, "text": "Membrana epirretiniana macular."}, {"position": 2, "text": "Agujero macular."}, {"position": 3, "text": "Trombosis de la vena central de la retina."}, {"position": 4, "text": "Degeneración macular senil."}, {"position": 5, "text": "Coriorretinopatía serosa central."}]'::jsonb, 5, 4, 'definitiva', 'De las cinco opciones, cuatro podrían ser compatibles con la clínica referida. Podríamos descartar inicialmente la coriorretinopatía serosa central porque por definición sucede en gente joven (hasta los 55 años, más o menos). La clave para diferenciar entre las cuatro restantes es que tenía drusas blandas en el fondo de ojo. Que si bien no es un “diagnóstico” (la pregunta podía estar mejor redactada) es un hallazgo relacionado con la degeneración macular asociada a la edad, o degeneración macular senil. La forma seca o atrófica cursa con pérdida visual lentamente progresiva. Pero la forma húmeda o exudativa produce de forma aguda o rápidamente progresiva una pérdida visual severa (normalmente por hemorragia subrretiniana acompañado de metamorfopsia (se deforma la imagen por el levantamiento de la retina). Una membrana epirretiniana suele llevar un curso más lento. En un agujero macular es más relevante la pérdida visual (puede referir también metamorfopsia, pero es menos probable en el momento agudo). En la trombosis de la vena central de la retina es más importante la pérdida visual y no suelen explicar metamorfopsia (pero la puede tener, por el edema macular).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6aa8c0c8318d', 'de22c851471419f2fa46152de3255750aa5a750c', NULL, NULL, NULL, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Ante un traumatismo directo sobre el lado derecho de la cara tras el cual el paciente presenta hematoma palpebral unilateral, diplopia en la mirada vertical y dificultad para la apertura de la boca, ¿cuál de las siguientes afirmaciones es cierta?', '[{"position": 1, "text": "Estamos con gran probabilidad ante una fractura de tercio medio facial tipo Lefort I."}, {"position": 2, "text": "Se trata probablemente de una fractura órbitomalar unilateral. El diagnóstico se comprobaría idealmente mediante TAC (tomografía axial computerizada)."}, {"position": 3, "text": "Se trata de una fractura de la base del cráneo a nivel del agujero carotídeo."}, {"position": 4, "text": "El diagnóstico probable es la fractura con dislocación del cóndilo mandibular."}, {"position": 5, "text": "Probablemente se asocia una fractura mandibular con una fractura del tercio medio facial tipo Lefort I."}]'::jsonb, 5, 2, 'definitiva', 'La diplopia en la mirada vertical es muy sugerente de que las paredes óseas de la órbita están afectadas. La fractura de Lefort tipo I no afecta al contenido orbitario. Conociendo esta información, la única respuesta correcta es la 2. Si dudábamos acerca de si la fractura de Lefort tipo I afectaba la órbita o no, simplemente mirad las respuestas. Quien puso la pregunta quiso asegurarse de que la única respuesta válida fuera la número 2; por eso añadió la coletilla de «pero por si acaso lo comprobamos con una TAC».', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-844cdef0f114', '5ea74330774829213b44e6fe727cfaa3beb91a67', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Una estudiante universitaria de 19 años acude a la consulta acompañada por sus padres refierendo sentirse en los últimos dos meses progresivamente más asténica, con pérdida de apetito y de peso y con mayores dificultades para concentrarse en los estudios. En la anamnesis también destaca que ha perdido interes en salir con las amigas, presenta ideas de muerte sin ideación autolítica y cogniciones pesimistas de futuro. Su peso es el 90% del considerado ideal por edad y género. No presenta fobia ponderal ni distorsión de la imagen corporal.', 'El diagnóstico más adecuado es:', '[{"position": 1, "text": "Anorexia nerviosa."}, {"position": 2, "text": "Trastorno de ansiedad."}, {"position": 3, "text": "Trastorno límite de la personalidad."}, {"position": 4, "text": "Distimia."}, {"position": 5, "text": "Trastorno depresivo mayor."}]'::jsonb, 5, 5, 'definitiva', 'En cuanto oímos lo de peso vamos hacia la anorexia nerviosa, pero la anorexia nerviosa tiene tres características: Pérdida significativa de peso originada por el propio enfermo, distorsión de la imagen corporal y amenorrea. Así que quitamos la 1. Uno pierde peso cuando se pone triste, se preocupa, etc… La 3 no tiene sentido en el MIR por la clínica -en la realidad la historia es otra y en psiquiatría todo es evolución-. La 4 ha de cumplir criterios temporales que aquí no se cumplen. Así que estamos entre la 2 y la 5. ¿Depresión o ansiedad? No hay clínica de ansiedad y además cumple citerios de depresión. A la pobre chica le ha caido un diagnóstico de depresión. La respuesta es la 5 (otra opción es que estuviese estudiando el MIR).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0b513eb0a232', '1352481beff344dc524a88af9a336d2901cb1e56', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Nos consulta una mujer de 84 años, por insomnio de conciliación. Tras fracasar a medidas de higuiene del sueño, se decide iniciar tratamiento farmacológico.', '¿Cuál de los siguientes fármacos selecionaría para la paciente?', '[{"position": 1, "text": "Diacepam."}, {"position": 2, "text": "Lormetacepam."}, {"position": 3, "text": "Fenobarbital."}, {"position": 4, "text": "Clordiacepóxido."}, {"position": 5, "text": "Cloracepato."}]'::jsonb, 5, 2, 'definitiva', 'Sabiendo que hemos tomado medidas de higiene del sueño, hemos explorado que le provoca el no dormir, y no duerme nueve horas y aún quiere dormir más,..entonces la respuesta menos lesiva es la 2. Porque es el de vida media más corta y no quiere que la señora se caiga al día siguiente.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8df6a1342e98', 'a8e93673d9d76ac21c9c8282bde0d1757af5ca27', NULL, NULL, NULL, false, false, 'Reumatología', 'Una paciente de 25 años con antecedentes de rash cutáneo tras exposición solar y poliartritis ocasionales en articulaciones de las manos que controla con antiiflamatorios no esteroideos presenta desde hace 15 días malestar general, sensación progresiva de debilidad generalizada y palidez. En la analítica destaca una Hemoglobina de 7 g/dL, VCM de 108 mm/h, 150000 plaquetas/mm3, 3000 leucocitos/mm3, LDH elevada, haptoglobina indectectable.', 'En el caso de elegir una sola prueba diagnóstica indique cuál de las siguientes determinaciones debe realizarse en primer lugar:', '[{"position": 1, "text": "Test de Coombs directo."}, {"position": 2, "text": "Anticuerpos antinucleares (ANA)."}, {"position": 3, "text": "Vitamina B12."}, {"position": 4, "text": "Ferritina."}, {"position": 5, "text": "Ácido fólico."}]'::jsonb, 5, 1, 'definitiva', 'El cuadro clínico y biológico de esta paciente hace sospechar una anemia hemolítica en el contexto de un lupus eritematoso sistémico. Si hay que escoger una sola prueba diagnóstica, y que ésta sea la primera, nos interesa confirmar la presencia de una anemia hemolítica autoinmune con el test de Coombs directo para iniciar tratamiento. El resto de pruebas pueden esperar...', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3feb84a20770', '44da4f804f5d986d812abd85cb7cb4e20c7c338a', NULL, NULL, NULL, false, false, 'Reumatología', 'Un paciente hiperuricémico que habitualmente toma 100 mg de alopurinol al día acude a urgencias con dolor agudo y signos inflamatorios en rodilla derecha. Se realiza artrocentesis y en el microscopio de luz polarizada se observan cristales intracelulares con birrefringencia negativa.', '¿Qué actitud terapéutica entre las que a continuación se indican, es la más adecuada en este caso?', '[{"position": 1, "text": "Suspender alopurinol e iniciar tratamiento con colchicina."}, {"position": 2, "text": "Suspender alopurinol y comenzar con AINE."}, {"position": 3, "text": "Añadir un AINE hasta que la crisis remita."}, {"position": 4, "text": "Aumentar la dosis de alopurinol a 300 mg/día."}, {"position": 5, "text": "Sustituir el alopurinol por un uricosúrico."}]'::jsonb, 5, 3, 'definitiva', 'Ante un artritis gotosa aguda (la presencia de cristales intracelulares con birrefringencia negativa lo confirma) en un paciente hiperuricémico que previamente seguía tratamiento con alopurinol se debe añadir un AINE hasta que la crisis remita. No se deben hacer cambios en el tratamiento hipouricemiante durante este periodo porque se altera la cadena metabólica del ácido úrico y puede empeorar la situación.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8cff31922c14', '90e3113037a5936e80740402f8469c3354bd565d', NULL, NULL, NULL, false, false, 'Reumatología', 'Una mujer de 75 años consulta por lesiones violáceas en manos y cuello junto a debilidad muscular progresiva de 3 meses de evolución.', '¿Qué pruebas diagnósticas, entre las que se indica, pueden ser de utilidad para el diagnóstico?', '[{"position": 1, "text": "Determinación de aldolasa sérica."}, {"position": 2, "text": "Electroencefalograma."}, {"position": 3, "text": "Biopsia de tejido celular subcutáneo."}, {"position": 4, "text": "Determinación de anticuerpos anti-músculo liso."}, {"position": 5, "text": "Estudio genético de sus descendientes."}]'::jsonb, 5, 1, 'definitiva', 'Ante este cuadro clínico, una posibilidad es que se trate de una dermatomiositis. De las pruebas propuestas, la determinación de la aldolasa sérica puede ser de utilidad. Su elevación es característica de esta enfermedad. La biopsia debería ser muscular y no subcutánea. Los anticuerpos anti-músculo liso no son los propios de esta enfermedad.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-bf409cbc71e1', 'd46d0cbac0835e2f4aeedbcc2f4bd2993bf8c791', NULL, NULL, NULL, false, false, 'Reumatología', 'Una paciente de 42 años de edad refiere dolor de características inflamatorias y tumefacción en ambas muñecas, 2ª y 3ª metacarpofalángicas e interfalángicas proximales de forma bilateral y tobillo izquierdo de 4 meses de evolución acompañada de rigidez matutina de más de una hora de duración. Esn la radiografía de manos se objetiva una erosión en la apófisis estiloides del cúbito en el carpo derecho. En la analítica destaca una Hb: 10 g/dL con VSG de 45 mm en 1ª hora, PCR 16 mg/L, factor reumatoide 160 UI/ML. Tras 6 meses de tratamiento con indometacina y metotrexato la paciente persiste con dolor y tumefacción de ambos carpos, rigidez matutina de 30 minutos de duración y una analítica donde destaca una VSG 30 mm en 1ª hora y una PCR 9 mg/dL.', 'Respecto a la actitud a tomar, cuál de las siguientes es verdadera:', '[{"position": 1, "text": "Suspender el tratamiento pautado por la falta de respuesta e iniciar prednisona a dosis altas para el control de los síntomas exclusivamente."}, {"position": 2, "text": "Mantener la actitud terapéutica tomada dado que sólo llevamos 6 meses y habría que esperar un mínimo de 9 meses para valorar respuesta terapéutica."}, {"position": 3, "text": "Si no existe contraindicación médica, valorar asociar al tratamiento un anti-TNF alfa."}, {"position": 4, "text": "Iniciar lo antes posible un segundo fármaco modificador de la enfermedad dado que no se podría iniciar tratamiento con terapia biológica sólo tras metotrexato."}, {"position": 5, "text": "Valorar iniciar tratamiento con terapia anti-CD20 asociada al metotrexato."}]'::jsonb, 5, 2, 'definitiva', 'Se trata de una paciente afecta de artritis reumatoide. En mi opinión, como en estos seis meses ha mostrado una clara mejoría clínica y biológica (dismininución de reactantes de fase aguda), mantendría la actitud terapéutica tomada y esperaría a una nueva valoración. Eso sí, considero que esta pregunta podría tener otra respuesta válida, la 3. Depende un poco de la actitud de cada reumatólogo. Si lo que se busca es una remisión de la enfermedad lo antes posible, se podría optar por valorar asociar un anti-TNF alfa...', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-31e7369247a1', '6e33c92bc5a07f7b0d524b7a87205e6584815952', NULL, NULL, NULL, false, false, 'Nefrología', 'Un paciente de 80 años con historia de hipertensión y en tratamiento con enalapril y espironolactona acude al hospital por astenia y debilidad muscular severa. La presión arterial es de 110/70 mmHg. En el ECG destacan ondas T picudas y elevadas, extrasístoles ventriculares y QT corto.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Hipercalcemia."}, {"position": 2, "text": "Hiperpotasemia."}, {"position": 3, "text": "Hipomagnesemia."}, {"position": 4, "text": "Hipocalcemia."}, {"position": 5, "text": "Hipernatremia."}]'::jsonb, 5, 2, 'definitiva', 'La respuesta correcta es: 2. Hiperpotasemia. Les ha dado por el potasio en este examen… La espironolactona, como diurético ahorrador de potasio, inhibe la acción de la aldosterona a nivel renal, siendo responsable de una disminución de la excreción de potasio. La hiperpotasemia produce trastornos de la repolarización que se traducen en la instalación de una T grande, simétrica, de base estrecha, visible en las derivaciones precordiales. El espacio QT acortado. Estas anomalías aparecen con una kaliemia de alrededor de 5,5 a 6 mmol/l. A partir de 6,5 mmol/l, las modificaciones electrocardiográficas son constantes, y están dominadas por los trastornos de la conducción (haciendo posibles las extrasístoles ventriculares).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-11b778bbc389', '248ab54f54ebd314fc499262c11881c398586430', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Si en un paciente con insuficiencia cardiaca crónica detectamos unas ondas v prominentes en el pulso venoso yugular y en la auscultación cardiaca se ausculta un soplo holosistólico en el área del apéndice xifoides que se acentúa con la inspiración profunda.', '¿Cuál es la valvulopatía responsable de esta exploración física?', '[{"position": 1, "text": "Insuficiencia mitral."}, {"position": 2, "text": "Insuficiencia pulmonar."}, {"position": 3, "text": "Insuficiencia tricúspide."}, {"position": 4, "text": "Insuficiencia aórtica."}, {"position": 5, "text": "Estenosis aórtica."}]'::jsonb, 5, 3, 'definitiva', 'Semiología básica. No obstante, razonamiento de emergencia: soplo sistólico, algo que en sístole tenía que estar cerrado y no lo está, o tenía que abrirse, y no lo hace: opciones 1, 3 y 5. Y si vemos repercusión en el pulso yugular, es que debe estar en cavidades derechas. Aparte de que la onda v aparece durante la sístole, mientras las aurículas se llenan: si el flujo del VD sube a la AD, lo que ocurrirá es que la onda v será grandísima…', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e0380f6eb1dd', '1f7fe121ce73865254b7d2db4608f38b6d276ddf', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Mujer de 56 años de edad, con antecedentes de esquizofrenia bien controlada, sin hábitos tóxicos. Ingresada por neumonía en lóbulo medio con un pequeño derrame pleural metaneumónico asociado y en tratamiento con levofloxacino 500 mg/24h. Presenta buena evolución clínica salvo por persistencia de febrícula y leucocitosis al sexto día de tratamíento. No se dispone de estudios microbiológicos.', 'La conducta más adecuada es:', '[{"position": 1, "text": "La evolución es normal, debe mantenerse tratamiento hasta completar los 10 días."}, {"position": 2, "text": "Se considera un fracaso terapéutico y debe modificar el tratamiento antibiótico."}, {"position": 3, "text": "Realizar toracocentesis para descartar empiema."}, {"position": 4, "text": "Asociar corticoides a dosis de 0.5 mg/Kg/día al tratamiento antibiótico."}, {"position": 5, "text": "Realizar broncoscopia con biopsia, aspiración y lavado broncoalveolar."}]'::jsonb, 5, 3, 'definitiva', 'Mientras persista la fiebre en una neumonía en evolución, existe el riesgo de empiematización, máxime si ya ha presentado un pequeño derrame al inicio del cuadro. El tratamiento antibiótico en principio es correcto y antes de plantear cambios de tratamiento, debe de evaluarse la posibilidad de empiematización.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-65954f59a450', '1205e1610d8335c48f488cd1b7978c6eca5c5635', NULL, NULL, NULL, false, false, 'Hematología', 'Una mujer de 33 años consulta por epistaxis de repetición, petequias y equimosis. Las pruebas de laboratorio muestran trombocitopenia con un recuento plaquetario de 4000 plaque­tas/microlitro. El diagnóstico de presunción inicial es de púrpura trombocitopénica inmuni­taria crónica (PTI).', '¿Cuál de las siguientes afirmaciones es FALSA respecto al diagnóstico de PTI?', '[{"position": 1, "text": "La presencia de adenopatías o esplenomega­lia en la exploración física sugiere un diag­nóstico diferente de PTI."}, {"position": 2, "text": "El análisis de médula ósea muestra un número disminuido de megacariocitos sin otras alteraciones."}, {"position": 3, "text": "El hemograma completo muestra trombocitopenia aislada con plaquetas a menudo gran­des, sin anemia salvo que exista una hemo­rragia importante o hemólisis autoinmune asociada (síndrome de Evans)."}, {"position": 4, "text": "El diagnóstico de PTI se establece por exclu­sión de otros procesos causantes de tromboci­topenia."}, {"position": 5, "text": "La determinación de anticuerpos antiplaque­ tarios no es precisa para establecer el diag­nóstico."}]'::jsonb, 5, 2, 'definitiva', 'Ante una trombocitopenia aislada no hay que perder de vista la exploración física; así, la presencia de adenopatías nos obliga a descartar la presencia de un linfoma, por ejemplo. La 1 es correcta. Al realizar una biopsia-aspirado de médula ósea se ve que el número de megacariocitos es normal o incluso está aumentado, el fallo no está en la médula sino en la sangre periférica, donde se destruyen las plaquetas. Así que... La respuesta falsa es la 2.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a9ee739d7735', 'b2ad3b199e1dff3814b11832088b317721e818e3', NULL, NULL, NULL, false, false, 'Dermatología', 'Una paciente de 14 años de edad en buen estado general presenta desde hace 4 dias una erupción cutánea generalizada muy pruriginosa formada por placas eritemato-edematosas de entre 2 y 15 cm de diámetro sin descamación con tendencia a adquirir una morfología anular que individualmente desaparecen en menos de 24 horas. Las mucosas están respetadas.', 'Su primera impresión diagnóstica sería:', '[{"position": 1, "text": "Urticaria."}, {"position": 2, "text": "Rubeola."}, {"position": 3, "text": "Toxicodermia."}, {"position": 4, "text": "Shock tóxico estafilocócico."}, {"position": 5, "text": "Escabiosis."}]'::jsonb, 5, 1, 'definitiva', 'Urticaria Aguda: se caracteriza por lesiones eritemato-edematosas, evanescentes pruriginosas, que duran menos de 24 horas, sin descamación. El estado general suele estar conservado. En los niños es más frecuente el patrón anular. Tanto en la rubeola como en la toxicodermia, el estado general no esta conservado. El Shock Estafilocócico, presenta afectación del estado general y además las lesiones son ampollosas. Las lesiones de la Escabiosis son interdigitales preferentemente, en forma de papulocostras que pueden seguir trayectos lineales.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5701bd3e1932', '1d01d4155cd47a4948bdd316fab14648b69810ec', NULL, NULL, NULL, false, false, 'Hematología', 'Un paciente de 29 años acude a su consulta con diagnóstico de aplasia medular severa.', '¿Cuál es el tratamiento de elección?', '[{"position": 1, "text": "Transfusiones periódicas y antibióticos."}, {"position": 2, "text": "Andrógenos y transfusiones de plaquetas."}, {"position": 3, "text": "Transplante alogénico de médula ósea si hermano HLA idéntico."}, {"position": 4, "text": "Transplante autólogo de médula ósea para evitar rechazo."}, {"position": 5, "text": "Ciclosporina A y globulina antitimocítica."}]'::jsonb, 5, 3, 'definitiva', 'Transfundir a este paciente y hartarlo de antibióticos es darle pan para hoy y hambre para mañana. Queremos algo más duradero. Los andrógenos y las transfusiones de plaquetas tampoco nos arreglan el problema. Nos quedan las otras tres opciones. Un transplante autólogo no es razonable, ya que la médula ósea de un paciente con aplasia medular es menor del 25%, de ahí poco se puede sacar. Por tanto, nos inclinamos por el transplante alogénico de médula ósea si tiene un hermano HLA idéntico, ya que ése es el tratamiento de elección según marca el protocolo de la Sociedad Española de Hematología y Hemoterapia para pacientes con menos de 40 años y aplasia medular severa. Respuesta correcta, la 3.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-51f589b3edf0', '84443cfe084a5697a283e424a54ea35d4aa87add', NULL, NULL, NULL, false, false, 'Endocrinología', 'Un paciente con soporte nutricional enteral, presenta a las 72 horas de iniciar la nutrición enteral, una analítica que muestra una hipofosforemia e hipopotasemia, con clínica de insuficiencia cardiaca. El paciente es diagnosticado de síndrome de realimentación.', 'Indique cuál de los siguientes factores NO se considera de riesgo para que un paciente presente este cuadro:', '[{"position": 1, "text": "Malnutrición calórica previa."}, {"position": 2, "text": "Anorexia nerviosa."}, {"position": 3, "text": "Obesidad no mórbida."}, {"position": 4, "text": "Ancianos."}, {"position": 5, "text": "Vómitos y diarrea prolongados."}]'::jsonb, 5, 3, 'definitiva', 'El síndrome de realimentación ocurre en pacientes con desnutrición previa expuestos a tratamiento nutricional bien oral, enteral o parenteral. Todas las respuestas son causa de desnutrición menos la 3.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b80826330eb8', 'ee72ad355022e0842b52cca1e7154e7140db72d1', NULL, NULL, NULL, false, false, 'Endocrinología', 'Una paciente de 56 años consultó por dolores en columna dorso-lumbar y dificultad progresiva para realizar las tareas habituales. En los últimos 5 años aumentó de peso, tiene equímosis con facilidad y se detectó hipertensión arterial. Exploración física: Obesidad de predominio central, facies redondeada, aumento de la grasa supraclavicular, disminución de la fuerza muscular proximal y algunas estrías rojizas en abdomen. Tiene glucemia de 136 mg/dL y el estudio radiológico mostró osteoporosis y aplastamientos vertebrales.', '¿Cuál le parece la interpretación y actitud más coherentes?', '[{"position": 1, "text": "Osteoporosis post-menopáusica, diabetes mellitus tipo 2 e hipertensión arterial esencial, con disminución de fuerza por polineuropatia diabética."}, {"position": 2, "text": "Es necesario descartar enfermedad de Cushing mediante test de supresión con dexametasona y realizar una TC craneal."}, {"position": 3, "text": "Sugiere un Cushing. Determinar cortisol libre urinario y ACTH basal, que sirve para orientar su etiología y seleccionar la técnica de imagen más apropiada."}, {"position": 4, "text": "Parece un Cushing. Si la ACTH basal es alta, puede ser por el uso de corticoides o un tumor suprarrenal, debiendo realizar una resonancia magnética."}, {"position": 5, "text": "Probablemente tiene un Cushing. Si la ACTH basal es baja, probablemente tenga un micro-adenoma hipofisario, debiendo realizar una TC craneal."}]'::jsonb, 5, 3, 'definitiva', 'Pregunta un poco enrevesada de diagnóstico del Síndrome de Cushing pero fácil si se tienen claro los pasos. Todos estamos de acuerdo en que parece que la paciente tenga un S. Cushing (descartamos la 1). Para el diagnóstico hay que medir el cortisol libre urinario, hacer un test de supresión con dexametasona o medir el cortisol en saliva nocturno. Si se confirma el hipercortisolismo, habría que buscar el origen; la medición de ACTH orienta el origen: suprimida en el hipercortisolismo de origen adrenal o uso prolongado de corticoides y elevada o normal si el origen es hipofisario o por secreción ectópica de ACTH. (Por tanto, la 4 y la 5 son falsas). Si la ACTH es baja habría que hacer un TAC de abdomen para localizar origen. Si la ACTH es normal o alta, habría que hacer una RMN de hipófisis (los adenomas hipofisarios responsables de S. de Cushing son muy pequeños y el TAC es la hipófisis es menos sensible que la RMN). Es muy importante realizar bien el orden para llegar a un diagnóstico adecuado: 1º: confirmar hipercortisolismo o s. Cushing, 2º: medir ACTH para orientar etiología. 3 º: prueba de imagen según niveles de ACTH. Por tanto, la respuesta 2 es falsa (el TAC de abdomen no es una prueba que sirva para descartar s. Cushing); sólo se debe hacer una prueba de imagen una vez diagnóstico claro de hipercortisolismo. Por tanto, la verdadera es la 3.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8d1df800e9a0', '27fea01d0d98e38e620db0e82ba74fb48b29d2a9', NULL, NULL, NULL, false, false, 'Endocrinología', 'Mujer de 52 años, natural de un pueblo de la Costa Brava que al ponerse crema en el cuello nota un bulto en la zona anterior, por lo demás asintomático; acude a su médico de cabecera que confirma la presencia de una masa firme de 2 cm. de diámetro máximo, liso, que asciende con la deglución. No adenopatías palpables.', '¿Qué pruebas solicitaría de entrada?', '[{"position": 1, "text": "Una determinación de tiroglobulina en sangre."}, {"position": 2, "text": "Una TC cervical."}, {"position": 3, "text": "Una determinación de anticuerpos antitiroideos (antitiroglubulina y antiperoxidasa) circulante."}, {"position": 4, "text": "Una punción con aguja fina."}, {"position": 5, "text": "Una determinación de T3 libre."}]'::jsonb, 5, 4, 'definitiva', 'Hace referencia a un nódulo tiroideo, y la prueba indicada es una PAAF (punción con aguja fina). He leído la respuesta que ha escrito Emilio sobre la impugnación; la pregunta está en el bloque de endocrino y parece que intenta dejar claro que se trata de un nódulo. La Ecografía facilita la PAAF pero no es obligatoria, un nódulo tiroideo de 2 cm puede punzarse sin eco. Es importante tener una analítica de función tiroidea previo a la punción; pero como habla de una paciente asintomática, parece claro que no está hipertiroidea. No creo se impugne y creo que es una pregunta que la mayoría habrá respondido bien.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-05f5e17b9e08', 'a94a5a7925a9481a213bde68870e537cabe9804e', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de 18 meses de edad, con calendario vacunal completo hasta la fecha, que consulta en el Servicio de urgencias por tumefacción de la rodilla derecha tras jugar en el parque, sin traumatismo evidente. En la anamnesis dirigida, la madre refiere que un tío de ella tenía problemas similares. La exploración ecográfica es compatible con hemartros y en la analítica que se realiza sólo destaca un alargamiento del APTT de 52’’ (normal 25-35’’).', '¿Cuál es la hipótesis diagnóstica más probable?', '[{"position": 1, "text": "Síndrome de Marfan."}, {"position": 2, "text": "Enfermedad de Von-Willebrand."}, {"position": 3, "text": "Enfermedad de Ehlers-Danlos."}, {"position": 4, "text": "Hemofilia A."}, {"position": 5, "text": "Enfermedad de Bernard-Soulier."}]'::jsonb, 5, 4, 'definitiva', 'Aunque otras enfermedades hemorrágicas pueden tener el tiempo de tromboplastina alargado, por la intensidad de la lesión y por el sexo del niño y los antecedentes familiares, el diagnóstico más probable es el de hemofilia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f1110604709b', '044159130dfc85f289c7aba16bf918cfd5d52ebe', NULL, NULL, NULL, false, false, 'Pediatría', 'Lactante de 13 meses que acude a urgencias por fiebre de hasta 39ºC de 48h de evolución sin otra sintomatología asociada. Exploración por órganos y aparatos sin hallazgos significativos, destacando buen estado general. Usted le iba entregar el alta domiciliaria pero el adjunto de Pediatría que está de guardia le pide sistemático de orina y un urocultivo por sondaje. En la orina destaca leucocituria ++, hematuria + y nitritos ++ y en el Gram de orina se observan bacilos Gram negativos. En la analítica de sangre no existe leucocitosis y la proteína C reactiva es de 50 mg/l. El adjunto le dice ahora que no es preciso que el niño ingrese y que le paute un antibiótico oral.', 'Señale el tratamiento antibiótico empírico menos adecuado en este caso:', '[{"position": 1, "text": "Amoxicilina."}, {"position": 2, "text": "Amoxicilina-clavulánico."}, {"position": 3, "text": "Cefuroxima-axetilo."}, {"position": 4, "text": "Cotrimoxazol."}, {"position": 5, "text": "Cefixima."}]'::jsonb, 5, 1, 'definitiva', 'El resto de fármacos son una buena elección en las infecciones de orina por bacilos gran negativos (el más probable: E. coli). La presencia de leucocitos+ nitritos en a orina es muy sugestiva de ITU. Y si el Gram de orina detecta bacterias G- probablemente se trate de una ITU por E Coli. Muchos E Coli son resistentes a amoxicilina.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e45747f418ac', '76a13960d563a0b0166faabf32de21f4f6ce29fb', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer 40 semanas de gestación en trabajo de parto con 6 cm de dilatación. Presenta patrón fetal decelerativo en registro cardiotocográfico por lo que se decide realizar microtoma de sangre fetal para valorar bienestar fetal. Resultado 7.22.', 'La conducta correcta es:', '[{"position": 1, "text": "Acidosis grave. Cesárea urgente."}, {"position": 2, "text": "Valor prepatológico repetir microtoma 15-20 minutos."}, {"position": 3, "text": "Acidosis moderada. Repetir microtoma en 1-2 horas."}, {"position": 4, "text": "Valor en limites normales, dejar evolución natural de parto."}, {"position": 5, "text": "Repetir en el momento posible error en la obtención de la toma."}]'::jsonb, 5, 2, 'definitiva', '• pH menor de 7.20 Valor patológico. Indicación de extracción fetal por la vía más rápida, en este caso una cesárea. • pH entre 7.20-7.25 Valor prepatológico. Repetir microtoma en 15-20 min. • pH mayor de 7.25. Valor dentro de los límites de la normalidad. Observación.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-597d928c7285', 'db21aa0f6047c310e540394fb75e68e8d72d42bd', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Una mujer de 32 años solicita consejo preconcepcional. La paciente refiere que fue sometida a una conización cervical por una lesión intraepitelial de alto grado (H-SIL) y que posteriormente sufrió tres abortos entre las 20 y 22 semanas de gestación. No tiene hijos vivos. En las tres ocasiones acudió a Urgencias con sensación de peso en hipogastrio y allí se constató que llegaba con una dilatación de 8cm y con las membranas amnióticas prominentes.', 'Nunca había sentido contracciones. ¿Qué consejo le daría para el próximo embarazo?', '[{"position": 1, "text": "Le pautaría una profilaxis con atosibán por vía oral durante todo el embarazo."}, {"position": 2, "text": "Le ofrecería la maduración pulmonar con corticoides a partir de las 19-20 semanas de gestación."}, {"position": 3, "text": "Le recomendaría realizar un cerclaje cervical programado a partir de la semana 14 de gestación."}, {"position": 4, "text": "Le aconsejaría no intentar más embarazos por el alto riesgo de recidiva."}, {"position": 5, "text": "Le recomendaría recurrir a técnicas de reproducción asistida."}]'::jsonb, 5, 3, 'definitiva', 'Se trata de un típico caso de incompetencia cervical (y esta paciente tiene como factor de riesgo la conización). Esta patología consiste en una dilatación del cérvix en ausencia de contracciones, y que requiere la realización de un cerclaje para evitar el aborto o el parto inmaduro. El cerclaje se realiza idealmente de forma electiva, programada, y no cuando la paciente llega a Urgencias “in extemis” (que también se hacen, pero con menor tasa de éxito… lo ideal es hacerlos en frío).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-295e430d97c2', '2ffccdb6d617158792b56e67e08189d0dc1704ce', NULL, NULL, NULL, false, false, 'Cirugía General', 'A un hombre de 45 años de edad se le realiza una vagotomía troncular y antrectomía con reconstrucción tipo Billroth II, por padecer una enfermedad ulcerosa péptica crónica con estenosis píloro-duodenal. Seis semanas después de la cirugía refiere que poco tiempo después (menos de media hora) de las ingestas presenta estado nauseoso, astenia y sudoración, mareos y retortijones abdominales generalmente acompañados de despeños diarreicos.', '¿Cuál de las siguientes es la actitud más adecuada para su manejo inicial?', '[{"position": 1, "text": "Aplicar tratamiento con un inhibidor de la somatostatina (octreótido)."}, {"position": 2, "text": "Seguir unas medidas dietéticas concretas."}, {"position": 3, "text": "Realizar un tratamiento de prueba con una benzodiacepina."}, {"position": 4, "text": "Realizar la búsqueda de un probable tumor neuroendocrino (p.ej. carcinoide)."}, {"position": 5, "text": "Indicar tratamiento quirúrgico para efectuar una gastroyeyunostomía antiperistáltica en Y de Roux."}]'::jsonb, 5, 2, 'definitiva', 'Las respuestas 1, 2 y 5 son tratamientos adecuados para el síndrome de dumping o postgastrectomía, pero la pregunta está enfocada al manejo inicial, por lo que la respuesta más adecuada parece la 2.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f3e56092fa4e', 'd5e7946418b4667c650784d5ea6c81cd8191ad6b', NULL, NULL, NULL, false, false, 'Nefrología', 'Paciente de 68 años que consulta por edemas y astenia. En la analítica realizada se constata creatinina de 5 mg/dl, hemoglobina de 10 gr/dl y una marcada hipogammaglobulinemia en suero a expensas de IgG, IgA e IgM. Un análisis de orina revela la presencia de cadenas ligeras kappa.', '¿Cuál es su sospecha diagnóstica?', '[{"position": 1, "text": "Enfermedad por depósito de cadenas ligeras kappa."}, {"position": 2, "text": "Síndrome nefrótico."}, {"position": 3, "text": "Amiloidosis."}, {"position": 4, "text": "Mieloma IgA con proteinuria Bence-Jones."}, {"position": 5, "text": "Mieloma de cadenas ligeras."}]'::jsonb, 5, 1, 'definitiva', 'Esta pregunta es mixta hemato-nefro. Es complicada, así que vamos a ir descartando opciones una por una. La opción 2, síndrome nefrótico, aparte de ser amplia e inespecífica, no sería valorable, ya que no nos dan la cuantificación de proteínas en orina (sólo nos dicen que el análisis de orina revela la presencia de cadenas ligeras kappa, no la cantidad). La opción 3 sería poco probable; en la amiloidosis, las cadenas ligeras que suelen depositarse son del tipo lambda. La opción 4 parece también poco probable, ya que en un mieloma IgA esperaríamos un pico monoclonal de dicha Ig, que en este caso no aparece. La duda que me surge es entre la 1 y la 5; yo optaría por la 1, porque esta entidad cumple con las características descritas (ausencia de pico monoclonal en la mayoría de los casos, fracaso renal agudo y presencia de cadenas kappa en orina), siendo el mieloma de cadenas ligeras una entidad algo más amplia, pero igualmente se podría dar como válida la opción 5.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d8d437d3ed2f', '1ca39cfc62a5b699fa43220d3cbc1a4a72b60a14', NULL, NULL, NULL, false, false, 'Nefrología', 'Hombre de 38 años que consulta por disnea y hemoptisis. En los análisis de sangre tiene creatinina 7 mg/dl, urea 250 mg/dl y anti-MBG (anticuerpos anti- membrana basal glomerular) positivos a título alto. Se realiza biopsia renal que muestra semilunas en el 75% de los glomérulos y en la inmunofluorescencia aparece un patrón depósito lineal de Ig.', '¿Cuál de las siguientes es la respuesta correcta?', '[{"position": 1, "text": "Se trata de una Nefropatía IgA con fracaso renal agudo."}, {"position": 2, "text": "Estaría indicada la realización de plasmaféresis."}, {"position": 3, "text": "Se trata de una glomerulonefritis membranosa."}, {"position": 4, "text": "El micofenolato mofetilo es el tratamiento inicial de elección."}, {"position": 5, "text": "La afectación glomerular está causada por la presencia de inmunocomplejos circulantes."}]'::jsonb, 5, 2, 'definitiva', 'La sospecha diagnóstica por los datos que nos dan (sobre todo los anticuerpos anti- MBG y la presencia de síndrome renopulmonar) es la de un síndrome de Goodpasture. El resto de datos (seminulas en la biopsia, depósito lineal IgG) apoya el diagnóstico. Sabiendo esto, las opciones se descartan fácilmente: la opción 1 nos habla de una nefropatía IgA (no es el caso porque los depósitos son de IgG); la opción 3 también queda descartada, al no tratarse de una GMN primaria, como la membranosa, sino de una glomerulopatía secundaria; la opción 4 también es falsa: el tratamiento inicial se realiza con corticoides y ciclofosfamida asociados a plasmaféresis; y la opción 5 es igualmente falsa, ya que el daño no es por inmunocomplejos circulantes, sino por anticuerpos depositados en la membrana basal glomerular. Esto nos deja la opción 2 como verdadera: como se ha dicho anteriormente, el tratamiento se realizaría combinando corticoides, ciclofosfamida y plasmaféresis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-21b4d64cae6f', 'f29019bef868c5610db04d413e6c69cee849ada9', NULL, NULL, NULL, false, false, 'Hematología', 'Muchacha de 19 años. sin antecedentes médicos de interés, salvo un cuadro gripal autolimitado 3 semanas antes, que acude al servido de urgencias por petequias y equimosis de aparición espontánea. En la exploración física la paciente se encuentra con buen estado general, afebril, normotensa y orientada en tiempo y espacio. Se observan petequias diseminadas por EEII y abdomen y equimosis pequeñas en zonas de decúbito. No se palpan adenopatías ni esplenomegalia. La analítica realizada ofrece los siguientes hallazgos: Hb 12.6 g/dL, leucocitos 5.500/mm3, plaquetas 7000/mm3. El estudio del frotis de sangre periférica ofrece una morfología eritrocitaria normal, recuento leucocitario diferencial normal y el recuento planetario es concordante con la cifra del autoanalizador sin observarse agregados plaquetares. Bioquímica y proteinograma, beta 2 microglobulina y LDH normal.', '¿Cuál cree que es, de los siguientes, el tratamiento inicial más adecuado?', '[{"position": 1, "text": "Transfusión de plaquetas."}, {"position": 2, "text": "Rituximab semanal."}, {"position": 3, "text": "Ciclofosfamida en pulsos de 4 días cada 21 días."}, {"position": 4, "text": "Plasmaféresis diaria."}, {"position": 5, "text": "Prednisona a 1 mg/día durante 2-3 semanas."}]'::jsonb, 5, 1, 'definitiva', 'Púrpura trombocitopénica idiopática, pero con muy bajas plaquetas, por lo que hay que reponer. La dosis de esteroide propuesta es demasiado baja.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b1a75d109600', '68e9c4cd18860ef543987e7805a8a76bca2d4c54', NULL, NULL, NULL, false, false, 'Hematología', 'Una paciente de 67 años en tratamiento con ticlopidina acude a urgencias con cefalea, astenia y petequias en extremidades inferiores. En la analítica presenta hemoglobina 8,2 g/dl, VCM 100 fl, plaquetas 25000/ul y leucocitos 7500/ul con formula normal. La cifra reticulocitos está elevada y el frotis de sangre se observa numerosos esquistocitos. Los estudios de coagulación (TTPA, TP y fibrinógeno) son normales. En la bioquímica destaca LDH 2700 UI/l y bilirrubina 2,6 mg/dl.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Purpura trombocitopénica autoinmune."}, {"position": 2, "text": "Purpura trombótica trombocitopénica."}, {"position": 3, "text": "Aplasia medular."}, {"position": 4, "text": "Trombopenia inducida por fármacos."}, {"position": 5, "text": "Coagulación intravascular diseminada."}]'::jsonb, 5, 2, 'definitiva', 'Típico de la ticlopidina. No solo trombocitopenia sino también cefalea, esquistocitos, LDH alta y bilirrubina alta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e99e79ab1c32', '3aaf2bce6f5c179ce56ecba6bf4f999712870af3', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Mujer de 40 años que consulta por aproximadamente 20 episodios al día de dolor intenso, periocular izquierdo de 15 minutos de duración, acompañado de intenso lagrimeo y rinorrea. Su exploración y resonancia magnética son normales.', 'Su tratamiento de elección sería:', '[{"position": 1, "text": "Indometacina."}, {"position": 2, "text": "Lamotrigina."}, {"position": 3, "text": "Verapamilo."}, {"position": 4, "text": "Prednisona."}, {"position": 5, "text": "Carbonato de litio."}]'::jsonb, 5, 1, 'definitiva', 'En esta pregunta nos presentan un caso para deducir un diagnóstico y luego indicar cual sería el tratamiento de elección. Tanto por las características del caso como por las respuestas se deduce que se trata de una cefalea trigémino-autonómica (dolor intenso, periocular con lagrimeo y rinorrea). La idea es realizar un diagnóstico diferencial fundamentalmente entre una cefalea en racimos (cuyo tratamientos incluyen las respuestas 2, 3, 4 y 5), una hemicranea paroxística (cuyo tratamiento de elección es la indometacina de la respuesta 1) y un SUNCT (Cefalea Neuralgiforme unilateral con inyección conjuntival y lagrimeo). La cefalea en racimos predomina en varones cuya duración puede variar entre 15-180 minutos, entre una vez cada 2 días, hasta 8 veces al día. La hemicranea paroxística predomina en la mujer, con episodios de dolor similares a la cefalea en racimos, pero con una duración más breve (2-30 min), y una frecuencia mayor (5-30 episodios al día). En cuanto al SUNCT las crisis son mucho más breves, de segundos de duración (5-240 segundos de duración) y suele ser refractaria a tratamiento. Por lo tanto el diagnóstico sería de una hemicranea paroxística y su tratamiento de elección es la indometacina (que además la respuesta es un criterio diagnóstico). Con lo cual respuesta correcta 1 (Indometacina). Todos los datos ofrecidos se basan en Criterios Diagnósticos de la International Headache Society.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1e2032a33d3d', 'b7b73690e20160ede9400f76cabcb16216b58fc0', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Mujer de 71 años, con antecedentes de artritis reumatoide en tto con sulfasalazina, prednisona y etanercept. Acude a URG por clínica de 72 horas compatible con Herpes Zóster facial afectando a a hemicara derecha, pabellón auricular, respetando frente y quemosis conjuntival.', '¿Cuál sería el tratamiento adecuado?', '[{"position": 1, "text": "Tto sintomático del dolor únicamente."}, {"position": 2, "text": "Tto tópico con aciclovir."}, {"position": 3, "text": "Tto ambulatorio con aciclovir, valaciclovir o famciclovir oral."}, {"position": 4, "text": "Ingreso hospitalario y tto con aciclovir o famciclovir iv."}, {"position": 5, "text": "Ig parenteral y vacunación."}]'::jsonb, 5, 4, 'definitiva', 'Creo que esta pregunta no está claramente en el temario de Infecciosas, y puede que se solape con OFT y DERMA, pero según tengo entendido, en una paciente inmunodeprimida y además con datos de afectación ocular, estaría indicado el ingreso para tratamiento intravenoso por el alto riesgo de complicaciones posibles.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2277d80175b4', '33c42a60f36ac68c9a3d9875c74368676bdf8670', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Una chica de 20 años acude a la consulta con un cuadro agudo de fiebre, adenopatías cervicales y rash cutáneo. Según refiere la paciente, hace 3 semanas tuvo una relación sexual que pudo ser de riesgo para contraer el virus del VIH.', 'Indica cuál de las siguientes respuestas es verdadera:', '[{"position": 1, "text": "Una serología VIH-1/VIH-2 negativa realizada por medio de la técnica de ELISA, descarta la posibilidad de que la paciente haya sido contagiada con el virus VIH."}, {"position": 2, "text": "El proceso clínico que padece la paciente no concuerda con el de la infección aguda por VIH."}, {"position": 3, "text": "Si el test de ELISA de la paciente fuera positivo, no sería necesario realizar nada más para el diagnóstico de infección por VIH."}, {"position": 4, "text": "La técnica de ELISA tiene una alta sensibilidad para el diagnóstico de infección por VIH, pero su especificidad es aún mayor."}, {"position": 5, "text": "Si el test de ELISA para diagnosticar VIH en la paciente fuera negativo, podríamos determinar por la técnica de PCR la carga viral en sangre."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta sencilla si tenemos claro el proceso diagnóstico del VIH. A primera vista, podríamos descartar directamente la respuesta 2 ya que sabemos que los cuadros mononucleosicos pueden ser expresión de la primera fase de una infección por VIH, máxime cuando tenemos el antecedente de un contacto de riesgo. Las respuestas 3 y 4 son también fácilmente descartables; el ELISA es una técnica muy sensible pero poco específica y SIEMPRE es necesaria la confirmación con una prueba Western-blot. La respuesta 1 y la 5 se contradicen si os dais cuenta, por lo que una de las dos es la correcta. En este caso, la falsa es la 1, se trata de una respuesta muy categórica (“descarta”) que no se adapta del todo a la realidad; como hemos dicho, el ELISA es una técnica muy sensible, por lo que un resultado negativo podría dejarnos bastante tranquilos, sin embargo, todos sabemos que no hay ninguna prueba médica que nos descarte nada con total certeza (a no ser que su sensibilidad sea del 100%, que no es el caso) y, por otra parte, podríamos decir que en este caso tenemos una alta sospecha clínica (el cuadro es sugestivo, y los antecedentes están ahí). Además, se da la circunstancia de que solamente hace 3 semanas desde el contacto, por lo que nuestra paciente se encuentra probablemente en el “periodo ventana” durante el que las técnicas serológicas pueden ser poco rentables. En conclusión, la respuesta que mejor nos cuadra sería la 5, en el periodo ventana puede estar indicada la realización de una carga viral para el diagnóstico (positivo si hay más de 10.000 copias), aunque esta prueba no se haga de forma rutinaria.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-af88e94e7a8a', '89e3dc016809442a2d03b400d21f1bf51ce9ec3c', NULL, NULL, NULL, false, false, 'Endocrinología', 'En una paciente de 30 años se encuentra una cifra de calcio de 11 mg/dl (normal menos de 10,5 mg/dl) durante un examen de empresas rutinario. La determinación de PTH fue de 45 pg/ml (VN 10-55 pg/ml). La historia es anodina, salvo por el hecho de que la madre y el abuelo paterno fueron diagnosticados de hiperparatiroidismo e intervenidos, aunque permanecieron hipercalcémicos.', '¿Qué prueba es más útil para confirmar el diagnóstico?', '[{"position": 1, "text": "25-OH D."}, {"position": 2, "text": "1,25-OH 2D."}, {"position": 3, "text": "Cociente calcio/creatinina en orina."}, {"position": 4, "text": "Reabsorción tubular de fosfatos."}, {"position": 5, "text": "PTHrP."}]'::jsonb, 5, 3, 'definitiva', 'Cociente calcio/creatinina orina. Se trata de hipercalcemia hipocalciúrica familiar o hipercalcemia familiar benigna. Trastorno autosómico dominante. Asintomático. No se curan tras tratamiento quirúrgico; se debe a mutación del receptor sensible al calcio. Pregunta difícil ya que hay conocer datos de una enfermedad que no se suele preguntar en el MIR.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-799545bf4c38', '79e3b2be07c5aa673b175a2e33e55658fe26f3fd', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Juan tiene 60 años, fuma de 2 paquetes/día desde hace años y refiere desde hace 6 meses tos persistente. Comprueba que su párpado izquierdo está más caído y que la pupila de ese ojo es más pequeña. Juan refiere que la parte medial de su mano izquierda está adormecida y con menos fuerza. Su médico comprueba la ptosis palpebral y la miosis izquierda; comprueba que Puede cerrar con fuerza ambos párpados simétricamente y que las dos pupilas responden correctamente a la luz. Además comprueba que no suda por la hemicara izquierda, que siente menos el pinchazo en la superficie interna de dicha mano y que tiene menos fuerza en la prensión de dicha mano.', 'Respecto a la sintomatología ocular, ¿dónde se localiza la lesión?', '[{"position": 1, "text": "Las fibras simpáticas, en algún nivel que abarcaría desde el hipotálamo a la columna de Clark interinedio-lateral de la médula dorsal."}, {"position": 2, "text": "El nervio motor ocular común izquierdo en el mesencéfalo."}, {"position": 3, "text": "El núcleo de Edinger-Westphal, encima del núcleo del nervio motor ocular común izquierdo."}, {"position": 4, "text": "Las fibras parasimpáticas, en algún nivel que abarcaría desde el núcleo de Edinger-Westphal hasta el músculo constrictor de la pupila izquierda."}, {"position": 5, "text": "El músculo tarsal exclusivamente."}]'::jsonb, 5, 1, 'definitiva', 'La pregunta seria mas de neurologia. Se trata de un sindrome de claude bernard horner y probablemente la correcta sea la 1. Pero por seguridad es mejor que lo revise un neurologo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1d3152bdfd83', '7715b43bda428e4fe33cc565e57e87575fa4b2fa', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Una mujer de 24 años es encontrada tirada en la calle por unos transeúntes. Al llegar el quipo de emergencias la encontraron con una saturación de oxígeno del 88% respirando aire ambiente y al examen pupilas puntiformes. Se la traslada a la urgencia del hospital más cercano, donde la gasometría arterial basal muestra: pH 7,25, PaC02 60 mmHg, Pa02 58 mmHg, bicarbonato de 26 mEq/1 y exceso de bases de -1.', 'En sangre el sodio es 137 mEq/1 y el cloruro 100 mEq/1:', '[{"position": 1, "text": "Insuficiencia respiratoria parcial."}, {"position": 2, "text": "Acidosis metabólica."}, {"position": 3, "text": "Acidosis respiratoria pura."}, {"position": 4, "text": "Alcalosis respiratoria por falta de cloro."}, {"position": 5, "text": "La gasometría solo puede ser de sangre venosa."}]'::jsonb, 5, 3, 'definitiva', 'La acidosis con PCO2 elevada, hipoxemia y bicarbonato normal, sugiere una acidosis respiratoria aguda de instauracion rápida probablemente por intoxicacion por drogas o farmacos.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7603ed7a0deb', '2d2ae80bf39bd2523f4d7ed037cdca6f4ee6e7a4', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Hombre de 65 años con antecedente de neoplasia de páncreas en curso de quimioterapia.', '¿Qué prueba diagnóstica es más coste-efectiva para confirmar la sospecha diagnóstica?', '[{"position": 1, "text": "Dímero D."}, {"position": 2, "text": "Resonancia magnética."}, {"position": 3, "text": "Flebografía."}, {"position": 4, "text": "Ecografía doppler venosa."}, {"position": 5, "text": "TAC helicoidal."}]'::jsonb, 5, 4, 'definitiva', 'La ecografia dopler es la prueba mas precisa y que permite posteriormente controlar la evolucion de la enfermedad de forma no invasiva.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5fc3d3df5ba8', '0510ecd9f81476fded02a08b0aef15f2c89292e7', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', NULL, 'Un paciente inmunodeficiente que presenta en la radiografía de tórax/TC una neumonía con el signo del halo menisco o contorno semilunar sugiere infección por:', '[{"position": 1, "text": "Staphylococcus aureus."}, {"position": 2, "text": "Streptococcus pneumoniae."}, {"position": 3, "text": "Candida albicans."}, {"position": 4, "text": "Pseudomonas aeruginosa."}, {"position": 5, "text": "Aspergillus fumigatus."}]'::jsonb, 5, 5, 'definitiva', 'El Signo del halo es característico de la aspergilosis pulmonar, y más en un paciente inmuodeprimido. Pero no es patognomónico, también se ha asociado a TBC, algunas neoplasias y la granulomatosis de Wegener.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4ad187eca821', 'ae5b8a99a1edbc076d86c810ff3a42afbcf57446', NULL, NULL, NULL, false, false, 'Dermatología', 'Joven que acude a urgencias por quemadura por llama de segundo grado del 10% de la superficie corporal, afectando al brazo derecho de forma extensa y circular. No se halla pulso arterial en la mano medido por doppler.', '¿Cuál es el tratamiento de elección?', '[{"position": 1, "text": "Curas con sulfadiacina argéntica oclusivas y evaluación de la profundidad a la semana."}, {"position": 2, "text": "Drenajes linfáticos y valorar un by-pass vascular."}, {"position": 3, "text": "Escarotomia o incisiones de descompresión de urgencia."}, {"position": 4, "text": "Conducta expectante."}, {"position": 5, "text": "Amputación de la extremidad."}]'::jsonb, 5, 3, 'definitiva', 'La pregunta tiene trampa: habla de una quemadura del 10% de la superficie corporal y el tratamiento de elección para quemaduras de segundo grado menores del 20% del BSA debe ser tópico y vigilar. Sin embargo hay un signo de alarma: no tiene pulso arterial y la quemadura es circunferencial al miembro. Esto supone una emergencia que, de dejarse evolucionar, comprometerá la viabilidad del miembro afecto y terminar en amputación: hay que realizar una escarotomía de urgencia con la finalidad aliviar la presión del tercer espacio sobre el tronco vascular arterial.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d06ee082a0e5', '1030c5045600dad7d45e05255b881b33bb8acd8d', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Joven de 18 años con antecedentes de asma, alergia a pólenes, ácaros y pelo de gato, acude a urgencias refiriendo sensación de detención de alimentos a nivel retroesternal con práctica incapacidad para deglutir su propia saliva. Refiere episodios similares en otras ocasiones que han cedido de forma espontánea en pocos minutos.', '¿Cuál de los siguientes es el diagnóstico más probable?', '[{"position": 1, "text": "Esófago de Barrett."}, {"position": 2, "text": "Anillo esofágico distal (Schatzki)."}, {"position": 3, "text": "Esofagitis infecciosa."}, {"position": 4, "text": "Esofagitis eosinofílica."}]'::jsonb, 4, 4, 'definitiva', 'Se trata de una disfagia intermitente. El esófago de Barrett no implica necesariamente una estenosis péptica, pero suponiéndola, esta es progresiva. La esofagitis infecciosa es más propia de pacientes inmunodeprimidos. Quedan el anillo esofágico distal y la esofagitis eosinofílica; ambas son posibles, pero la insistencia en la carga atópica del paciente indica la probabilidad de que se trate de la última de las opciones.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0d2489f5bcb7', 'f1ef5b3a970c493b0d73ed6746ab43a946bd752f', NULL, NULL, NULL, false, false, 'Aparato Digestivo', NULL, 'Indique la situación clínica que, en relación con la infección por virus de la hepatitis B, presenta un paciente de 5 años procedente de Nigeria, con exploración física normal y con la siguiente serología frente a hepatitis B: HBsAg + / ANTI-HBs – / HbeAg – / ANTI-HBe + / ANTI-HBc IgM – / ANTI-HBc IgG + / DNA VHB +:', '[{"position": 1, "text": "Infección aguda."}, {"position": 2, "text": "Infección crónica."}, {"position": 3, "text": "Paciente vacunado."}, {"position": 4, "text": "Portador asintomático."}]'::jsonb, 4, 4, 'definitiva', 'Que tenga anticuerpos contra el core implica contacto natural, y que sea IgG, que no es agudo. La ausencia del antígeno e descarta la replicación activa. Y la persistencia del antígeno de superficie (HBsAg) y del ADN del virus indica que sigue presente. En conjunto, indican que se trata de un portador asintomático. Los portadores del mutante pre-core habitualmente tienen periodos sintomáticos recurrentes y mayor inflamación hepática. No habría datos suficientes para descartarlo por completo, pero no está entre las respuestas e indican la exploración física completamente normal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d0e8f8732c1f', 'f7c687318da53d6840bb3391c1f4c333561626ef', NULL, NULL, NULL, false, false, 'Anatomía Patológica', 'Mujer de 59 años que presenta diarrea crónica acuosa de 4 meses de evolución. En la endoscopia, la mucosa no mostraba aspectos relevantes. En concreto, no se observaron úlceras o áreas friables. Se realizó biopsia del colon transverso. En el estudio histopatológico se reconoció un área engrosada por debajo del epitelio de revestimiento superficial, que era más evidente mediante técnica de tricrómico de Masson y que conllevaba atrofia y denudación epitelial. También se apreció un claro incremento en la densidad de linfocitos intraepiteliales.', '¿El diagnóstico de la lesión intestinal es?', '[{"position": 1, "text": "Colitis ulcerosa cronificada."}, {"position": 2, "text": "Colitis pseudomembranosa."}, {"position": 3, "text": "Colitis colágena."}, {"position": 4, "text": "Enfermedad de Crohn fibrosante."}]'::jsonb, 4, 3, 'definitiva', 'En este caso, la presencia de engrosamiento de la capa de colágeno subepitelial, más evidente con el tricrómico de Masson (tinción especial que permite diferenciar las fibras de colágeno), es patognomónica de la colitis colágena. La atrofia junto con la denudación epitelial son características de esta enfermedad, la cual no suele causar alteraciones macroscópicas de la mucosa. Un incremento de la densidad de linfocitos intraepiteliales y la ausencia de mención de alteraciones arquitecturales de las criptas (características de la colitis ulcerosa y la enfermedad de Crohn) nos apoyan en este diagnóstico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-503017d6a236', '9c3e0dc0cc6a69f65991e89b4cb015c88acbf46b', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un paciente de 52 años ingresa en el Hospital por neumonía grave. Con tratamiento antibiótico adecuado mejora del cuadro respiratorio. Tras 4 días de estancia en planta se complica su evolución por la aparición de un proceso diarreico grave.', '¿Cuál sería el microorganismo más frecuentemente responsable de este cuadro?', '[{"position": 1, "text": "Salmonella entérica."}, {"position": 2, "text": "La propia bacteria causante de la neumonía que se ha hecho resistente al antibiótico."}, {"position": 3, "text": "Campylobacter jejuni."}, {"position": 4, "text": "Clostridium difficile."}, {"position": 5, "text": "Yersinia enterocolítica."}]'::jsonb, 5, 4, 'definitiva', 'En este caso y, dado el tratamiento antibiótico instaurado así como la gravedad de la diarrea, parece que estemos ante una infección por Clostridium. La opción 2 es poco creíble, la verdad, por mucho que los pacientes con NAC puedan asociar diarrea, es poco probable que una bacteria sea sensible a un antibiótico al inicio de cuadro y deje de serlo a los 3 días.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2bcf43a6e1bc', '76b302225ce67dc0e418824b28f4d36b44aca5c1', NULL, NULL, NULL, false, false, 'Dermatología', 'Gustavo acude a Urgencias con lesiones cutáneas y malestar general de varios días de evolución. Tiene lesiones psoriasiformes en tronco con afectación de palmas y plantas. También presenta una inflamación articular asimétrica no supurativa y enrojecimiento ocular bilateral así como erosiones en glande. En la anamnesis posterior Gustavo reconoce un contacto sexual de riesgo 20 días antes.', '¿Cuál es su diagnóstico?', '[{"position": 1, "text": "Infección por VIH."}, {"position": 2, "text": "Sífilis secundaria."}, {"position": 3, "text": "Síndrome de Reiter."}, {"position": 4, "text": "Eritema multiforme."}]'::jsonb, 4, 3, 'definitiva', 'Está describiendo un síndrome de Reiter de libro: queratodermia palmo-plantar, artritis y manifestaciones oculares, junto a seguramente una uretritis por clamidia, quizá asintomática (no explican exudado uretral). Naturalmente, además el paciente puede tener una infección por VIH o incluso una sífilis secundaria (además del Reiter).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-daee0d1015ff', 'cdd95e03d0b4dd733061ce5531c6a7610775f4f6', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Hombre de 25 años sin antecedentes de interés que acude a urgencias con fiebre, cefalea, mialgias, náuseas, vómitos, dolor abdominal, ictericia e inyección conjuntival, 2 semanas después de haber viajado a Thailandia para participar en una regata en agua dulce.', '¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Malaria."}, {"position": 2, "text": "Esquistosomiasis."}, {"position": 3, "text": "Leptospirosis."}, {"position": 4, "text": "Rabia."}]'::jsonb, 4, 3, 'definitiva', 'El antecedente de contacto con agua dulce en un área endémica orienta a leptospirosis, y en la clínica encontramos también ictericia e inyección conjuntival que nos orienta también a leptospirosis y no se relaciona tan característicamente con los otros tres patógenos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-30de8d9ba0b6', '9386f3f1e2a43caa8a08d6c3ad192babc7b5d8d8', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Una mujer de 24 años de edad consulta al haber apreciado adenopatías inguinales. En el interrogatorio no se recoge la presencia de ninguna molestia local ni datos sugerentes de infección de transmisión sexual. En la exploración se aprecian dos adenopatías, una en cada ingle, de 1 cm de diámetro mayor, blandas, móviles, no dolorosas. No se aprecia ninguna lesión cutánea en miembros inferiores, ano o periné.', '¿Qué prueba considera imprescindible?', '[{"position": 1, "text": "Una serología de lúes puesto que lo más probable es que se trate de una infección por Treponema pallidum."}, {"position": 2, "text": "Una exploración ginecológica a fin de descartar un cáncer de ovario."}, {"position": 3, "text": "Por las características clínicas parece tratarse de unos ganglios normales y no deben hacerse exploraciones complementarias."}, {"position": 4, "text": "Debe realizarse una prueba de Paul-Bunnell a ﬁn de descartar una mononucleosis infecciosa."}]'::jsonb, 4, 3, 'definitiva', 'En el adulto sano pueden presentarse ganglios inguinales palpables de hasta 2 centímetros que pueden considerarse dentro de la normalidad. No está justificado el estudio complementario de estos ganglios linfáticos normales.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-95b1be2bd11c', 'f69963302b59c14f9604127c0e6b31c53fd2debc', NULL, NULL, NULL, false, false, 'Oncología', 'Paciente de 66 años diagnosticado de adenocarcinoma de páncreas estadio IV hace 8 meses. Sigue tratamiento con morfina de liberación retardada 200 mg/12 horas vía oral, parafina y lactulosa. Desde hace 15 días refiere parestesias y dolor lancinante ocasional en zona lumbar derecha y periumbilical que no cede con ingesta de morfina de rescate. La exploración neurológica es normal.', 'Señale cual sería el manejo más apropiado:', '[{"position": 1, "text": "Realizar tomografía axial computarizada y evaluar compresión nerviosa ya que se trata de dolor neuropático."}, {"position": 2, "text": "Valorar tratamiento neurolítico ya que el dolor neuropático es de difícil control."}, {"position": 3, "text": "Disminuir la dosis de morfina ya que es ineficaz en este tipo de dolor."}, {"position": 4, "text": "Administrar amitriptilina o gabapentina, dexametasona y aumentar la dosis de morfina."}]'::jsonb, 4, 4, 'definitiva', 'Tenemos delante a un paciente con dolor neuropático, que por el origen del tumor, lo más probable es que se deba a afectación del plexo celiaco. Es importante tener un diagnóstico radiológico de cara a un posible tratamiento local, como el tratamiento neurolítico o bloqueo del plexo. No obstante no debemos dejar al paciente sin un tratamiento que le pueda aliviar sino solucionar la situación actual. Se encuentra tomando analgesia del tercer escalón de la OMS que es claramente insuficiente, con lo que precisará de coadyuvantes; aunque los opiáceos para el dolor neuropático no son muy eficaces, no disminuiremos la dosis sino que asociaremos los coadyuvantes. Manejaríamos al paciente con gabapentina y corticoides (respuesta 4 verdadera); no le disminuiríamos la dosis de morfina (respuesta 3 falsa), y mientras tanto le iríamos pidiendo el TAC (o RM abdominal) para posteriormente valorar el bloqueo del plexo (respuestas 1 y 2 para el manejo futuro).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f60a70fe9cc4', '6ad4378b9824a436fe117078cd9be19214c83c5f', NULL, NULL, NULL, false, false, 'Reumatología', 'Un hombre de 37 años presenta un cuadro de artritis de las metacarpofalángicas de ambas manos y una pleuritis derecha. En la exploración se aprecia eritema malar bilateral.', 'Se detectan anticuerpos antinucleares positivos (titulo 1/640), con anticuerpos anti-DNA nativo también positivos; anti-Sm negativos ¿Cuál sería el tratamiento inicial de elección de este paciente?', '[{"position": 1, "text": "Glucocorticoides a altas dosis."}, {"position": 2, "text": "Glucocorticoides y micofenolato."}, {"position": 3, "text": "Antiinflamatorios no esteroideos y antipalúdicos."}, {"position": 4, "text": "El cuadro probablemente será autolimitado y no precisa tratamiento."}]'::jsonb, 4, 1, 'definitiva', 'Es un LES con afectación articular, cutánea y serositis. El tratamiento son CE a moderadas-altas dosis. El micofenolato no es nunca un tratamiento en fase aguda sino en el mantenimiento, ni ha demostrado utilidad en afectación articular.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-79c9e52de7f7', '3e5aab57ee7d157eee441daa1c3c58adc7cae8d4', NULL, NULL, NULL, false, false, 'Reumatología', 'Usted valora a un paciente de 66 anos con dolor inguinal acentuado con la bipedestación prolongada algunos días al mes.', 'Una radiografía simple de caderas muestra estrechamiento del espacio articular femoro-acetabular, esclerosis y ostefitos ¿Cuál es su actitud?', '[{"position": 1, "text": "Hago el diagnóstico de coxartrosis y envío al traumatólogo para colocar una prótesis de cadera."}, {"position": 2, "text": "Inicio tratamiento con opioides débiles que han demostrado evidencia en detener la progresión de la enfermedad."}, {"position": 3, "text": "Instauro tratamiento con paracetamol, explico que la evolución es muy variable y la indicación quirúrgica depende de la funcionalidad y control del dolor."}, {"position": 4, "text": "Por las características radiológicas descritas, necesito una RMN de cadera antes de tomar una decisión terapéutica."}]'::jsonb, 4, 3, 'definitiva', 'Es una coxartrosis. El criterios quirúrgico depende de la sintomatología del paciente y del fracaso a tratamiento médico. Ninguna medicación frena ni modifica el curso de la enfermedad. No es necesaria una RMN, no aporta nada. El tratamiento es médico y secuencial empezando con el primer escalón analgésico de la OMS.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-73015435631c', '2cc5271847011b7b3684e6345fbedcdd04c615d7', NULL, NULL, NULL, false, false, 'Endocrinología', 'Acude a la consulta una mujer de 30 años de edad refiriendo en los tres últimos meses ansiedad, pérdida de unos 6 kg de peso y sensación de “nerviosismo”. En la exploración fisica destaca taquicardia, hiperreflexia y ausencia de bocio. En la analítica realizada los valores de la TSH son < a 0.01 microU/mL, la T4 está elevada y los niveles de tiroglobulina descendidos. Al realizarle una gammagrafía se detecta una ausencia de captación en la región tiroidea.', '¿Cuál le parece el diagnóstico más probable?:', '[{"position": 1, "text": "Tirotoxicosis facticia."}, {"position": 2, "text": "Hipertiroidismo por Enfermedad de Graves."}, {"position": 3, "text": "Teratoma de ovario (estruma ovárico)."}, {"position": 4, "text": "Tiroiditis subaguda."}]'::jsonb, 4, 1, 'definitiva', 'Respuesta 2 incorrecta: La enfermedad de Graves se caracteriza por hipertiroidismo y una o más de las siguientes características: bocio, exoftalmos y mixedema pretibial. Respuesta 4 incorrecta: El síntoma más obvio de la tiroiditis subaguda es el dolor en el cuello. Algunas veces, el dolor puede extenderse a la mandíbula o a los oídos. El agrandamiento doloroso de la glándula tiroidea puede durar semanas o meses. Y suele presentar nivel bajo de la hormona estimulante de tiroides (TSH) en suero. Nivel alto de T4 libre en suero. Nivel alto de tiroglobulina en suero. Respuesta 4 incorrecta: Tumor muy raro.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-35fb35a9b212', 'ff2108b9a3656df99df9f72bc993a0c6f867125f', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', NULL, 'En un paciente diagnosticado de epilepsia que presenta episodios de falta de respuesta a estímulos externos, movimientos irregulares de las cuatro extremidades, ojos cerrados, emisión de llanto y movimientos pélvicos, de cinco a veinte segundos de duración y que no responden al tratamiento con fármacos antiepilépticos. ¿Cuál es el estudio complementario con mayor probabilidad de aclarar el diagnóstico?', '[{"position": 1, "text": "Monitorización vídeo-EEG para diagnóstico de pseudocrisis (crisis psicógenas)."}, {"position": 2, "text": "Holter ECG para diagnóstico de cardiopatía arrítmica."}, {"position": 3, "text": "EEG de rutina para diagnóstico del tipo de epilepsia (generalizada o foc)."}, {"position": 4, "text": "Resonancia magnética cerebral para detectar lesiones epileptógenas (displasia cortical, tumor, esclerosis temporal medial)."}, {"position": 5, "text": "Determinación de glucemia capilar para diagnóstico de hipoglucemia."}]'::jsonb, 5, 1, 'definitiva', 'Respuesta 1 correcta: El cuadro descrito es muy sugestivo de pseudocrisis con movimientos asíncronos de las extremidades, movimientos pélvicos, llanto y mala respuesta a fármacos antiepilépticos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fbf5b5539068', '8d1444cfb139170ac4f15b16341fdf64a915d3a3', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Mujer de 51 años que acude a urgencias por disminución brusca de agudeza visual, cefalea intensa, nauseas y vómitos. Hipotensa y afebril. Presenta oftalmoparesia derecha por afectación de III par craneal. Una TC craneal evidencia una masa en la región selar hiperdensa con erosión de las apófisis clinoides anteriores.', '¿Cuál es la actitud de seguir?', '[{"position": 1, "text": "Sospecharía meningitis química derivada de la rotura de un tumor epidermoide e iniciaría de inmediato tratamiento con corticoesteroides."}, {"position": 2, "text": "Indicaría la realización de una angiografía cerebral para descartar un aneurisma, ya que lo más probable es que estemos ante un caso de hemorragia subaracnoidea y la masa que se evidencia en la TC sea un aneurisma trombosado paraselar."}, {"position": 3, "text": "Ingreso en UCI y tratamiento del shock que padece la paciente y una vez estabilizada practicar resonancia cerebral para cirugía programada."}, {"position": 4, "text": "Determinación de bioquímica y hemograma urgentes, inicio de terapia con corticoesteroides a dosis elevadas y cirugía transesfenoidal urgente."}, {"position": 5, "text": "Punción lumbar para descartar meningitis bacteriana previo inicio de antibioterapia empírica. Una vez estabilizada la paciente estudio de la masa selar."}]'::jsonb, 5, 5, 'definitiva', 'La apoplejía hipofisaria es un síndrome caracterizado por la aparición brusca de cefalea acompañada de alteraciones de la motilidad ocular y un grado variable de insuficiencia hipofisaria. La causa suele ser un rápido crecimiento de una masa hipofisaria secundaria a un evento vascular (infarto o hemorragia). Los síntomas generales pueden incluir desde vómitos o náuseas a irritación meníngea. La compresión sobre el quiasma y el nervio óptico puede causar diferentes déficits campimétricos (generalmente hemianopsia bitemporal mayor en los cuadrantes superiores) y disminución de agudeza visual, incluso ceguera. Si la masa crece hacia los laterales de la silla turca puede comprimir los nervios oculomotores, siendo el nervio ocular motor común el más frecuentemente afectado, por su trayecto más medial en el seno cavernoso. La prueba de elección para el diagnóstico de la apoplejía hipofisaria es la RMN, ya que el TC puede no distinguir la región con la suficiente claridad como para distinguir cambios degeretativos o quísticos de sangrados previos. El hallazgo en el TC de cráneo de erosión de las apófisis clinoides anteriores puede ir a favor de una lesión crónica, que a raíz de un fenómeno vascular agudo ha provocado la sintomatología. El manejo de estos pacientes pasa por un control estricto de las alteraciones hidroelectrolíticas y corrección de los déficits hormonales. En situaciones inestables como en el caso que se describe, con importante alteración visual, la intervención quirúrgica suele ser de elección, con descompresión transesfenoidal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6c0a3db95dd7', '55f0ab4683222c62880dbb35bc338c5b5ef3b5ff', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Un paciente de 64 años de edad, agricultor, ex­ fumador (5 años), EPOC y afecto de artritis reumatoide en tratamiento corticoideo. Consulta en urgencias por presentar cefalea intensa de 2 días de evolución con desviación de comisura bucal. Como antecedente, relata que tras cuadro gripal hace un mes, persiste tos, expectoración purulenta y ocasionalmente hemoptoica, febrícula, anorexia, astenia y pérdida de peso. A su llegada se aprecia la existencia de fiebre de 38.2ºC, abscesos cutáneos múltiples en manos, espalda y nalgas (algunos con trayectos fistulosos) y parálisis facial central derecha, infiltrados apicales con pequeño derrame pleural asociado en la radiografía de tórax y leucocitosis con neutrofilia.', 'Entre los siguientes diagnósticos de sospecha consideraría MÁS probable:', '[{"position": 1, "text": "Neoplasia pulmonar con metástasis cerebrales."}, {"position": 2, "text": "Tuberculosis diseminada."}, {"position": 3, "text": "Nocardiosis."}, {"position": 4, "text": "Aspergilosis."}]'::jsonb, 4, 4, 'definitiva', 'La nocardia tipicamente puede afectar a inmunosuprimidos, en especial con alteración de la inmunidad celular como es la producida por los esteroides, y puede cursar con afectación pulmonar, abscesos cerebrales y cutáneos. La Tuberculosis puede afectar a pulmón y cerebro pero no abscesos cutáneos. Aspergillus tampoco afecta a piel.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-351c5a0948b8', '2504bf4aa31fed733249c50ffe70fd855bf19d7c', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Encontrándose de guardia médica en el Servicio de Urgencias de su hospital, tiene que atender a un paciente de 64 años de edad con insuficiencia respiratoria aguda. Su estado clínico es crítico, con baja saturación de oxígeno e inestabilidad hemodinámica. Se realiza Rx urgente de tórax que muestra atelectasia de 2/3 del pulmón derecho. Se procede a intubación orotraqueal y ventilación en modo asistido, con Fi02 de 1,0. En una gasometría arterial practicada posterior­ mente obtenemos estos valores: pH 7,23; Pa02 60 mmHg y PaC02 30 mmHg.', '¿Cuál es la causa de la hipoxemia?:', '[{"position": 1, "text": "Cortocircuito."}, {"position": 2, "text": "Hipoventilación."}, {"position": 3, "text": "Baja presión de 02 inspirado."}, {"position": 4, "text": "Enfermedad neuromuscular."}]'::jsonb, 4, 1, 'definitiva', 'La FiO2 de 1 y la hiperventilación con la ventilación mecánica, demostrada por la baja PCO2, no consiguen remontar suficientemente la PO2, debido a un trastorno en la V/Q, con shunt probable en la zona de la atelectasia pulmonar, probablemente aguda, dado que el pulmón no ha podido crear mecanismos compensatorios de limitar la perfusión en las zonas mal ventiladas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9f5c3dfa4194', 'd47690f8a708422ded63a8aa8572664c9167cd70', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Hombre de 52 años que acude al servicio de Urgencias por cefalea y fiebre (37,8°C) de 2 dias de evolución. En las últimas horas asocia además diticultad para la nominación y comprensión. En la exploración realizada no se observa rigidez de nuca siendo lo más llamativo la presencia de una afasia mixta, El fondo de ojo es normal. La TC craneal muestra una tenue hipodensidad en lóbulo temporal izquierdo sin efecto de masa y sin captación de contraste.', '¿Cuál de las siguientes afirmaciones es la correcta?:', '[{"position": 1, "text": "Una meningitis bacteriana es la primera impresión diagnóstica y hay que iniciar cuanto antes tratamiento con cefalosporina de 3a generación."}, {"position": 2, "text": "Lo más probable es que el LCR de este paciente nos muestre una pleocitosis de predominio linfocitario con glucorraquia normal."}, {"position": 3, "text": "Sospecharíamos una encefalitis límbica."}, {"position": 4, "text": "Se trata de un absceso cerebral en fase inicial."}]'::jsonb, 4, 2, 'definitiva', 'El cuadro que nos describen es típico de una meningoencefalitis vírica, más concretamente por VHZ, con importante tropismo por el lóbulo temporal, causando febrícula y en muchos casos afasia, por lo que la opción correcta sería la 2, ya que el líquido cefalorraquídeo normalmente muestra una pleocitosis linfocitaria moderada, con glucorraquia normal. No son correctas el resto por: La primera porque no es una meningitis bacteriana que cursaría con más fiebre, la tercera porque la encefalitis límbica normalmente cursa de forma afebril con cambios de comportamiento y la última porque la imagen que nos describen no es un absceso, bien delimitado.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-80b38836f052', '86661835a1f9c86cb03f97f12f0e727042744126', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', NULL, 'Mujer de 70 años con antecedente de anorexia,pérdida de peso, molestias en la musculatura y articulaciones proximales más dolorimiento en la región temporo-mandibular que acude al servicio de urgencias por pérdida de visión unilateral (movimiento de manos), de aparición brusca e indolora (defecto pupilar aferente). ¿Qué prueba solicitaría en primer lugar con fines diagnósticos?', '[{"position": 1, "text": "Punción lumbar."}, {"position": 2, "text": "Proteína C Reactiva."}, {"position": 3, "text": "Angio Resonancia Magnética."}, {"position": 4, "text": "Ecografía carotídea."}]'::jsonb, 4, 2, 'definitiva', 'Nos presentan el caso de una amaurosis monocular de perfil vascular, además en una mujer mayor con antecedentes de pérdida de peso y lo que parecen síntomas de claudicación mandibular y polimialgia reumática, por lo que la primera causa que hay que pensar es en una arteritis de células gigantes como causante de la NOIA, por lo que de las opciones la correcta sería la 2. La 4 nos la plantearíamos si nos contaran una NOIA pero de características no arteríticas (sin toda esa sintomatología acompañante).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9147d87bfc0d', '4f6c05ce3a45b534a58c5856d24683c1498d0589', NULL, NULL, NULL, false, false, 'Pediatría', 'Una mujer se presenta en la consulta con su hija de 3 años porque le ha detectado ligero desarrollo mamario desde hace 3 meses sin tomar medicación alguna ni objetivarse antecedentes relevantes en la historia. Efectivamente, el examen físico muestra un estadio Tanner IV, sin crecimiento del vello púbico o axilar. Los genitales externos son normales. La ecografía revela un pequeño útero y la radiología una edad ósea de 3 años.', '¿Qué actitud se debería adoptar?', '[{"position": 1, "text": "Seguimiento cada 3-4 meses, ya que se trata de una condición temporal que a menudo se resuelve sola."}, {"position": 2, "text": "Biopsia mamaria."}, {"position": 3, "text": "Mamografía."}, {"position": 4, "text": "Administración de análogos GnRh."}]'::jsonb, 4, 1, 'definitiva', 'Esta pregunta está regular planteada, demasiado desarrollo para unas exploraciones complementarias normales… Parece que nos quieren presentar una pubertad precoz (o una telarquia prematura) pero no aportan ningún dato analítico y los datos de la ecografía son ambiguos (habría que dar por supuesto que con un pequeño útero se están refiriendo a un útero prepuberal, pero no aportan datos a cerca del tamaño ovárico). Nos presentan el caso de una niña con desarrollo mamario avanzado de tres años de edad, en principio sin ninguna causa asociada (en principio no toma fármacos que puedan aumentar el nivel de estrógeno en sangre, no parece usar cremas corporales ni ingesta importante de carne de pollo). Si seguimos el esquema diagnóstico ante una telarquia prematura o sospecha de pubertad precoz, se solicita edad ósea y ecografía abdominal (la EO no está adelantada como ocurre en la pubertad precoz, y damos por supuesto que con un útero pequeño se quieren referir a un útero prepuberal); según las exploraciones complementarias que nos dan, no parece una pubertad precoz, salvo la clínica (Tanner IV). Estrictamente, sin datos hormonales analíticos, parece que podríamos marcar la opción 1, siendo necesario hacer un seguimiento estrecho de la niña. Si damos por hecho todos los datos anteriores, podríamos descartar la opción 4, que sería el tratamiento de una pubertad precoz central. Respecto a la opción de mamografía, en pediatría se usa la ecografía mamaria, y en este caso estaría indicada si nos dijesen que existe una asimetría mamaria (descartamos la opción 3). Respecto a la biopsia mamaria únicamente estaría indicada ante signos de alarma.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8080cf10de87', 'e0116855de4c6083204417b98d31f46c20c02d8c', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Mujer de 68 años, con antecedentes de 2 episodios depresivos mayores a lo largo de su vida, que consulta por síntomas de tristeza, decaimiento, anhedonia, astenia y anorexia compatibles con un nuevo episodio depresivo. Se pautan 10 mg de escitalopram y se evalúa 2 semanas después. En esta revisión la paciente refiere estar muy bien, se despierta temprano muy hiperactiva y con ‘muchas ganas de hacer cosas’, dice tener mucha energía y está más habladora de lo que en ella es habitual. No refiere estar irritable y es capaz de dormir 6 horas continuadamente.', 'Ante esta situación, ¿qué pensaría que tiene la paciente?', '[{"position": 1, "text": "Trastorno bipolar tipo I."}, {"position": 2, "text": "Hipomanía inducida por fármacos."}, {"position": 3, "text": "Respuesta normal al escitalopram."}, {"position": 4, "text": "Demencia frontal."}]'::jsonb, 4, 3, 'definitiva', 'En esta pregunta cabría sospechar la posibilidad de un viraje afectivo ante la introducción del fármaco antidepresivo, por lo que refiere la paciente, pero si nos fijamos hay un dato claro que “descarta” el viraje hipo/maníaco y es la capacidad de mantener el sueño. Dos semanas es poco tiempo para que el fármaco haya hecho efecto pleno sobre el estado del ánimo, pero sí puede aparecer una activación inicial que los pacientes a veces no llevan muy bien (algo que no parece ser el caso). En esta paciente está indicado mantener el tratamiento y reevaluar en no más de un mes.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-768561fcc44c', 'd1184ed830d6575600deed5160e0061f1e2affd2', NULL, NULL, NULL, false, false, 'Oftalmología', 'Mujer de 70 años con antecedentes de anorexia, pérdida de peso, molestias en la musculatura y articulaciones proximales más dolorimiento en la región temporo-mandibular que acude al servicio de urgencias por pérdida de visión unilateral (movimiento de manos), de aparición brusca e indolora (defecto pupilar aferente).', '¿Qué prueba solicitaría en primer lugar con fines diagnósticos?:', '[{"position": 1, "text": "Punción lumbar."}, {"position": 2, "text": "Proteína C reactiva."}, {"position": 3, "text": "Angio Resonancia Magnética."}, {"position": 4, "text": "Ecografía carotídea."}]'::jsonb, 4, 2, 'definitiva', 'Se trata de una mujer con pérdida brusca y indolora y grave (sólo ve el movimiento de las manos) de la visión de un ojo. No nos da mucha información de la exploración ocular, sólo que hay un defecto pupilar aferente. Nos tenemos que ayudar de los síntomas sistémicos para diagnosticar el problema. Se trata de una mujer de edad avanzada con síntomas típicos de polimialgia reumática, y el dolor en la región temporomandibular es muy sugerente. Se trata de una arteritis de células gigantes o arteritis de la temporal. La manifestación ocular más habitual es la neuropatía óptica isquémica anterior. En el fondo de ojo seguramente veríamos un edema de papila de ese ojo, de coloración blanco yeso. Es muy característico de estas neuropatías ópticas isquémicas tan severas el defecto pupilar aferente. Sospechando una arterítis de células gigantes, hay tres marcadores analíticos que están característicamente altos: la PCR, la VSG y el recuento plaquetario. En primer lugar solicitaremos alguno de estos parámetros y ponerle tratamiento muchas veces sin esperar confirmación por la biopsia. Por lo tanto, la opción 2 es la correcta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-854e39da4e5c', 'ae6cb0123d42dc621207d8e80983685b38bb022c', NULL, NULL, NULL, false, false, 'Oncología', 'Mujer de 67 años diagnosticada de un carcinoma ductal infiltrante de mama y sin historia familiar de neoplasia.', '¿Qué estudios adicionales deben realizarse en el tumor por sus implicaciones clínico-terapéuticas?:', '[{"position": 1, "text": "Estudio fenotípico completo mediante citometría de flujo."}, {"position": 2, "text": "Estudio de receptores hormonales y de HER2."}, {"position": 3, "text": "Estudio de receptores hormonales, ecadherina y estudio de familiares de primer grado."}, {"position": 4, "text": "Estudio de BRCA l-2 y estudio de familiares de primer grado."}]'::jsonb, 4, 2, 'definitiva', 'Actualmente la clasificación molecular del cáncer de mama se basa en el estudio de los receptores hormonales, el HER2 y el índice de proliferación celular del tumor (Ki67). Tenemos cuatro tipos fundamentales: Luminal (A: RRHH+, HER2- y Ki67 bajo y B: RRHH+, HER2+/ – y Ki67 alto), HER2 + (RRHH -, HER2 + y Ki67 alto) y Basal Like ó triple negativo (RRHH -, HER2 – y Ki67 alto).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7144125ba8a7', 'e785b6b1388f3857cc104fc1058d8522e933751b', NULL, NULL, NULL, false, false, 'Atención Primaria', 'Acude al domicilio de un paciente oncológico que últimamente no tiene bien controlado el dolor. En la exploración física parece que no hay evidencia de progresión tumoral, no revela ningún dato de interés de lo conocido previamente. En la anamnesis el cuidador principal manifiesta que el paciente tiene dolor a las 8 h de haber recibido la dosis basal pautada de morfina cada 12 h.', 'Esta situación clínica se denomina:', '[{"position": 1, "text": "Tolerancia"}, {"position": 2, "text": "Hiperalgesia"}, {"position": 3, "text": "Dependencia"}, {"position": 4, "text": "Ineficacia"}]'::jsonb, 4, 1, 'definitiva', 'La respuesta correcta es la 1. El enunciado define perfectamente un fenómeno de tolerancia en el que el paciente se ha “acostumbrado” a la dosis y necesita más para poder tener el mismo efecto analgésico.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a56c284c8563', 'f5d9835cd2469bb00f676c2bbd6cd514575ea36f', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Mujer de 87 años con antecedentes de hipertensión arterial, ingresada hace 48 horas en la unidad coronaria por infarto agudo de miocardio con elevación de ST de localización anterior. Avisa por disnea. En la exploración destaca soplo sistólico con frémito, irradiado al borde esternal derecho que no estaba presente al ingreso.', '¿Qué complicación sospecha usted?', '[{"position": 1, "text": "Insuficiencia cardiaca por necrosis extensa."}, {"position": 2, "text": "Aneurisma anterior."}, {"position": 3, "text": "Rotura de la pared libre del ventrículo izquierdo."}, {"position": 4, "text": "Rotura en el tabique interventricular."}]'::jsonb, 4, 4, 'definitiva', 'Rotura del tabique interventricular. Las complicaciones mecánicas son típicas en infartos en mujeres ancianas. Asimismo, un soplo que no estaba presente indica un flujo de sangre anormal: las complicaciones más frecuentes son la insuficiencia mitral, que cursaría con un soplo musical o piante, y la CIV, que cursa con un soplo irradiado al borde derecho (piensa en la dirección del flujo de sangre).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8b1ac7737beb', '7b44c3cd042ba144d7c14540eb9e591d7d4bd705', NULL, NULL, NULL, false, false, 'Endocrinología', 'Mujer de 34 años que ingresa para estudio de poliuria y polidipsia. En las primeras 24 horas de ingreso se constata una diuresis de 8,2 litros y se obtiene una analítica que muestra una glicemia de 96 mg/dL, natremia de 148 mEq/L y osmolalidad plasmatica de 309 mOsm/kg con osmolalidad urinaria de 89 mOsmlkg.', '¿Qué prueba diagnóstica debe realizarse a continuación?', '[{"position": 1, "text": "Test de infusión de suero salino hipertonico para determinación seriada de hormona antidiurética."}, {"position": 2, "text": "Test de deshidratación (test de Miller)."}, {"position": 3, "text": "Administración de desmopresina con control seriado de osmolalidad en orina."}, {"position": 4, "text": "Determinación de hormona antidiurética en plasma."}]'::jsonb, 4, 3, 'definitiva', 'Nos encontramos ante poliuria. Inicialmente descartamos diabetes mellitus (nuestra paciente tiene una glucemia normal, de 96mgr/dl). Los datos analíticos nos orientan a diabetes insípida (osm en plasma alta con osm urinaria baja). Ahora debemos diferenciar entre diabetes insípida central (falta de ADH) o nefrogénica (la ADH no ejerce su acción a nivel renal). Ello se consigue mediante el test de vasopresina (administración intravenosa de ADH y medir de nuevo la osmolaridad urinaria). Por tanto, la respuesta correcta es la opción 3.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8e40475c5c15', '0194d6ac89cb14be3a3215c3b83906931dc03cae', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Hombre de 45 años que consulta por tos productiva, dolor pleurítico en costado derecho y fiebre de 48 h de evolución. Se aprecia una saturación basal de O2 del 88% y estertores en base derecha. La RX de tórax muestra una consolidación basal derecha. Tiene antecedentes de infección por VIH bien controlada con antirretrovirales linfocitos CD4 550 ce/uL y carga viral de VlH indetectable).', '¿Cual de los tratamientos antimicrobianos empíricos que se señalan a continuación le parece mas adecuado?', '[{"position": 1, "text": "Cefiriaxona 2 g y azitromicina 500 mg cada 24 horas."}, {"position": 2, "text": "Cefiriaxona 2 g, azitrornicina 500 mg cada 24 horas y trimetoprim-sulfametoxazol 5 mg/kg/8 h (basado en dosis de trimetoprim)."}, {"position": 3, "text": "Metil-prednisolona 40 mgdía, cefiriaxona 2 g IV 124 h y trimetoprim-sulfametoxazol 5 mg/kg/8 h (basado en dosis de trimetoprim)."}, {"position": 4, "text": "Meropenem I g/8 h y vancomicina I g/l2 h."}]'::jsonb, 4, 1, 'definitiva', 'La primera opción parece ser la correcta, por la baja probabilidad de infección por P. jirovecii en paciente con más de 500 linfocitos CD4 y carga viral indetectable. Lo más probable es que sea infección por neumococo que cubrimos con Ceftriaxona y con azitromicina cubrimos las llamadas “atípicas”. Meropenem es un antibiótico de espectro demasiado amplio, que tendría opción en una neumonía intrahospitalaria por la P. aeruginosa, agente bacteriano que también puede causar neumonía a pacientes VIH, pero no es lo frecuente.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a14d28a9cf82', '32dfb1ba75fc62b507bc25c6383289dbd9bba3d8', NULL, NULL, NULL, false, false, 'Medicina Preventiva y Epidemiología', 'Luis es un joven de 25 años que sufrió esplenectomia tras accidente de bicicleta hace 1 año. Tiene un perro que le mordió hace 24 horas y le ha producido una pequeña herida en la mano derecha. Acude a su centro de salud (situada a 3 horas del hospital mas cercano) por fiebre de 39ºC, dolor en la herida y malestar general. A la exploración PA 100/60 mm Hg, FC 110 latidos por minuto, ligera inflamación en la herida sin pus.', '¿Cual de las siguientes actuaciones esta mas indicada en este momento?', '[{"position": 1, "text": "Enviar al hospital para vacunar de rabia y tétanos y mantener en observación."}, {"position": 2, "text": "Limpiar la herida y administrar ganunaglobulina inespecífica intramuscular."}, {"position": 3, "text": "Dar 400 mg de moxifloxacino oral y enviar al hospital."}, {"position": 4, "text": "Dar clindamicina 600 mg oral cada 8 horas y observación."}]'::jsonb, 4, 3, 'definitiva', 'Al considerar un paciente “especial” a un esplenectomizado, este recibiría tratamiento antibiótico lo antes posible aunque la herida no aparezca infectada. Hay que tener que el perro es suyo (se debería preguntar si el animal está correctamente vacunado) y si el paciente está correctamente vacunado (5 dosis de tétanos, no requeriría antitetánica); realizar una notificación de Agresión por Animal, para observación de este y tomar medidas en caso de que esto sea necesario.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-487403c1d3a8', 'af75abd6a7d5f679b93b6869c130cebccdecdbb1', NULL, NULL, NULL, false, false, 'Medicina Preventiva y Epidemiología', 'Mujer de 38 años de edad de profesión veterinaria, encargada de la vigilancia de animales salvajes y de ayudar a partos de ganado doméstico. Comienza con un cuadro de fiebre alta con escalofríos, cefalea, mialgias y tos no productiva que interpreta como un proceso gripal. Acude por presentar dolor torácico. En la radiografía de tórax se objetivan infiltrados pulmonares bilaterales en campos inferiores. Se realiza una prueba serológica con elevación de titulos de anticuerpos frente a antígenos en fase II.', '¿ Cual de las siguientes afirmaciones es CIERTA?', '[{"position": 1, "text": "La forma de trasmisión de esta entidad es por garrapatas."}, {"position": 2, "text": "Tanto la doxiciclina como la hidroxicloroquina son eficaces para tratar las formas agudas de esta enfermedad."}, {"position": 3, "text": "En su forma aguda también presenta, generalmente, elevación de anticuerpos frente a antígenos en fase l."}, {"position": 4, "text": "La mortalidad en las formas agudas es casi inexistente."}]'::jsonb, 4, 4, 'definitiva', 'Como posible enfermedad consideraría la Brucelosis, típica del ganado (leche, aborto, secreciones genitales…). Se presenta con una sintomatología de cuadro pseudogripal (cefalea, artalgias, mialgias, fiebre…) y otros síntomas en función de la vía de entrada. En el caso de nuestro caso, al asistir partos de animales la entrada es por vía respiratoria por lo que los infiltrados pulmonares y el dolor torácico se deben a la bacteria. El tratamiento varía en función de la afectación y la mortalidad es muy baja, casi nula. Siendo más preocupante su morbilidad y la afectación en embarazadas. Importante: es muy frecuente en trabajadores de ganado (veterinarios, granjeros, mataderos…) si lees algo tipo “asiste partos de animales de ganado”, “trabaja en granja”, “es veterinario” sospecha Brucelosis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-169788e0971d', '352726cbc90bb2a6e73138ed933cbb375f6a369a', NULL, NULL, NULL, false, false, 'Pediatría', 'Niña de 10 años que viene a revisión de salud. La exploración física es normal con un peso y una talla en el percentil 50 y TA 109/65. Un análisis de orina de rutina muestra una densidad específica de 1035 pH6 sangre 2+ sin proteínas. El sedimento urinario muestra 5-10 hematíes por campo.', '¿Cuál sería la conducta más apropiada a seguir?', '[{"position": 1, "text": "Determinar creatinina y nitrógeno en sangre."}, {"position": 2, "text": "Derivar a la niña para la realización de una cistoscopia."}, {"position": 3, "text": "Determinar anticuerpos antinucleares y complemento."}, {"position": 4, "text": "Volver a repetir el sedimento de orina en 15 días."}, {"position": 5, "text": "Realizar una tomografía axial computarizada abdominal."}]'::jsonb, 5, 4, 'definitiva', 'La respuesta correcta es la 4. Lo que no me queda muy claro es lo de “análisis de orina de rutina” porque no se suelen hacer en un niño sano asintomático. La microhematuria sin síntomas asociados, puede ser un hallazgo sin significado patológico y hay que confirmarla en un nuevo sedimento posterior (aunque no sé si a los 15 días o más tarde).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-bd9fd1eab48d', '87ba1924f4932a1ed9ba964bad0e0669a409b677', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un hombre presenta en la exploración neurológica un déficit sensitivo termoalgésico en la pierna izquierda asociado a una pérdida de sensibilidad vibratoria y posicional en la pierna derecha. Al mismo tiempo presenta torpeza y pérdida de fuerza distal en la pierna derecha y un reflejo cutáneo plantar derecho en extensión.', '¿Cuál de las siguientes afirmaciones es correcta?:', '[{"position": 1, "text": "Es un síndrome centromedular tipo siringomielia."}, {"position": 2, "text": "Es un síndrome hemimedular."}, {"position": 3, "text": "Es un patrón de lesión medular transversa."}, {"position": 4, "text": "Es un patrón de lesión bulbar lateral."}]'::jsonb, 4, 2, 'definitiva', 'Describen un cuadro de hemisección o Brown-Sequard típico. Afectación motora y cordonal posterior ipsilateral con afectación contralateral de dolor y temperatura.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-be41d61ac1dc', '0371f4c2b348783c9e34cd4444df5d1556678007', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Una mujer de 65 años consulta por debilidad en la mano derecha que se ha extendido en pocos meses a otros territorios musculares de ambos brazos y piernas, de predominio distal. En la exploración hay atrofia y fasciculaciones en distintos territorios metaméricos con sensibilidad conservada.', 'Existe un signo de Babinski bilateral. ¿Cual es la prueba diagnóstica que confirmaría el diagnóstico de sospecha?', '[{"position": 1, "text": "TC cerebral."}, {"position": 2, "text": "Estudio electromiografico."}, {"position": 3, "text": "RM cerebral."}, {"position": 4, "text": "Potenciales evocados multimodales."}]'::jsonb, 4, 2, 'definitiva', 'La respuesta es la 2, un EMG, que sería la prueba diagnóstica para confirmar la sospecha diagnóstica de ELA, las pruebas de imagen tanto el TC, pero sobre todo la RM nos ayudarían a descartar, pero no nos confirmarían el diagnóstico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b668226e2bac', 'ea138eb158ef68774b72a7ad06b9b422e82ca56b', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Un hombre de 58 años, a las tres semanas de un esguince grave de tobillo presenta, de forma rápidamente progresiva, disnea de reposo, mareo y síncope. Al llegar al hospital tiene hipotensión (PA sistólica 80 mmHg, diastólica 40 mmHg) y mala perfusión. Es intubado y conectado a ventilación mecánica y se inicia noradrenalina. El ecocardiograma muestra signos de hípertensién pulmonar. En la angio-TC se observan múltiples defectos de replección ocupando ambas arterias pulmonares principales.', '¿Cuál de los siguientes tratamientos se asociaría a una mejoría hemodinámica más rápida en este caso?', '[{"position": 1, "text": "Heparina sódica en perfusión intravenosa."}, {"position": 2, "text": "Tromboendartectomía."}, {"position": 3, "text": "Fibrinolisis sistémica con rt-PA (alteplase) 100 mg intravenoso."}, {"position": 4, "text": "Filtro en vena cava inferior."}]'::jsonb, 4, 3, 'definitiva', 'El paciente presenta un tromboembolismo pulmonar que, además de ser bilateral, produce una afectación hemodinámica severa, una situación de shock y requiere ventilación mecánica. No nos dicen que tenga ninguna contraindicación para realizar fibrinolisis, así que ésta sería la opción más adecuada por su rapidez de administración y acción. La heparina sódica se reserva para casos en los que el paciente está estable. La tromboendarterectomía podría realizarse de urgencia en centros seleccionados (no disponible en todos) en pacientes en los que estuviera contraindicada la fibrinolisis sistémica, o bien en centros donde la experiencia de esta técnica sea constatada y se pueda realizar con rapidez. El filtro en vena cava inferior es un tratamiento que se indica en el momento agudo pacientes estables, cuando tienen contraindicada la anticoagulación; o bien a posteriori, como profilaxis, en este grupo de pacientes. Las indicaciones de realización de fibrinolisis del último documento de consenso de la SEPAR incluían pacientes en riesgo intermedio (podrían beneficiarse de ella) y riesgo alto. Clasifican el riesgo intermedio como PESIs ≥ 1 o PESI III-IV. En este subgrupo, parece que se benefician más de la fibrinolisis los pacientes con disfunción de ventrículo derecho, troponina o BNP superior al límite de corte y trombosis venosa profunda. En el subgrupo de pacientes de riesgo alto (definido por hipotensión o criterios de shock cardiogénico), está mucho más claro el uso de fibrinolisis sistémica, como el caso que nos presentan en la pregunta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5cf757c58b73', '6d02bc1d84bc16d895cafe033bbc40255de160d5', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 73 años con antecedentes de obesidad, diabetes mellitus tipo 2, hipertensión arterial y dislipemia. Consulta por dolor insoportable en la rodilla derecha de 5 días de evolución, sin trauma previo. Exploración: rodilla globulosa, varo moderado, extensión y flexión limitadas por dolor, dolor difuso medial. En la radiografía se aprecian osteofitos y pinzamiento leve de la interlínea medial.', '¿Cuál sería su manejo inicial?:', '[{"position": 1, "text": "Explicación del diagnóstico, reposo relativo, paracetamol 1g/8h más metamizol 500 mg/ 8 h naproxeno de rescate."}, {"position": 2, "text": "Derivación preferente a consultas externas de Traumatología para valoración de prótesis total cementada."}, {"position": 3, "text": "Derivación preferente a consultas externas de Traumatología para valorar desbridamiento artroscópico."}, {"position": 4, "text": "Solicitud de resonancia magnética preferente para evaluación de meniscopatía,, quiste de Baker y/o tendinitis."}]'::jsonb, 4, 1, 'definitiva', 'Nos están describiendo una crisis aguda de dolor en un paciente con gonartrosis. En esta situación lo primero es resolver la crisis de dolor y plantear un tratamiento adecuado conservador para dicha artrosis (1 correcta). No se plantea de entrada una artroplastia de rodilla por lo que 2 es falsa. No nos están contando una clínica infecciosa para sospechar de una artritis que justificara un desbridamiento y lavado por lo que 3 es falsa. En un paciente con gonartrosis va a existir siempre meniscopatía, forma parte de los cambios degenerativos. El quiste de Baker solo nos interesaría en una crisis de dolor severa en el diagnóstico diferencial con una trombosis profunda y se valora con una ecodoppler, en el cuadro de gonartrosis no tiene ningún valor detectar un quiste de Baker. Las tendinitis se diagnostican mediante la exploración no con RMN. Por todo ello la 4 es falsa.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-efc5f44cb35e', '9e08f18c70e4112de8e9c8dff1dfd0cc71b03c0c', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Niño de 7 años traído a urgencias tras caerse de un columpio sobre la mano derecha. No tiene antecedentes de interés. Presenta deformidad en dorso de tenedor de la muñeca e impotencia funcional, con situación neurovascular distal normal.', '¿Qué lesión espera encontrar en la radiografía urgente que solicita?', '[{"position": 1, "text": "Fractura – luxación de Monteggia."}, {"position": 2, "text": "Fractura de la cabeza radial."}, {"position": 3, "text": "Epifisiolisis distal del radio."}, {"position": 4, "text": "Fractura en tallo verde de cúbito."}]'::jsonb, 4, 3, 'definitiva', 'Con la deformidad y dolor en radio distal esperamos una fractura a dicho nivel por lo que marcamos 3. Sin embargo, la veo impugnable dado que también podría tener de forma concomitante una fractura en tallo verde de cúbito aunque la lesión principal sea la del radio.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-996cea7b4e4f', '84a000a2b02ab4a6f9e94eff076d71ee9a892968', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'El diagnóstico más probable de un paciente de 74 años que desde hace dos meses comienza con dolor lumbar irradiado a miembros inferiores, claudicación neurógena y limitación a la extensión el tronco es:', '[{"position": 1, "text": "Hernia discal de L4-L5."}, {"position": 2, "text": "Fractura vertebral lumbar."}, {"position": 3, "text": "Inestabilidad vertebral L5-S1."}, {"position": 4, "text": "Estenosis de canal lumbar."}]'::jsonb, 4, 4, 'definitiva', 'Nos están mostrando un cuadro de estenosis de canal lumbar (Respuesta 4 correcta). El paciente muestra el cuadro clínico característico: Dolor lumbar que se alivia al flexionar el tronco hacia delante, dolor radicular con afectación de miembros inferiores y claudicación neurógena. Una lumbalgia en un paciente mayor de 60 años acompañada de debilidad en piernas en la marcha, que tiene que interrumpirla a una determinada distancia, llamada claudicación nerviosa, es el cuadro típico de la estenosis. El paciente se alivia flexionando la columna hacia delante porque amplía el canal lumbar y empeora con la extensión…', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-878e588497ae', '692ad7563ceaa78232285f0e8ef31004c37996a4', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 70 años, diabética e hipertensa que sufre una caída en su domicilio, presentando una herida de 9 cm que comunica con un foco de fractura de la tibia derecha. Radiográficamente se observa una fractura oblicua corta de tercio medio-distal de tibia. Se opera de urgencias mediante limpieza (Friederich) y colocación de un clavo endomedular acerrojado. A los 11 meses presenta una pseudoartrosis atrófica de tibia con supuración en la zona de la herida.', '¿Cuál será su mejor opción terapéutica inmediata?:', '[{"position": 1, "text": "Triple antibioterapia (grampositivos, gramnegativos y anaerobios) y limpieza de la herida quirúrgica, retirando los cerrojos distales para favorecer la consolidación ósea."}, {"position": 2, "text": "Actitud expectante y tratamiento antibiótico con quinolonas."}, {"position": 3, "text": "Aporte de injerto autólogo y de factores de crecimiento (BMP 2 y 7) para estimular el proceso de consolidación ósea, que está retardando."}, {"position": 4, "text": "Retirada del clavo, desbridamiento, colocación de fijador externo y antibioterapia ajustada a los resultados de los cultivos."}]'::jsonb, 4, 4, 'definitiva', 'Lo primero es tratar la infección y para ello debemos retirar todo el material de osteosíntesis, desbridar y dar antibioterapia. La fijación en este caso es mejor externa para evitar todo el material alrededor de la zona afectada por lo que 4 es correcta y 1 y 2 no. La 3 se plantearía después de vencido el cuadro infeccioso. TRATAMIENTO • Tratamiento antibiótico supresivo: indicado en pacientes de tipo C de Ciemy, consiste en antibioterapia oral prolongada durante al menos 6 meses para «enfriar» la reagudización del cuadro clínico. • Tratamiento curativo: incluye una primera cirugía con desbridamiento agresivo, de tipo tumoral, de todos los tejidos afectos, irrigación profusa, estabilización con fijador externo si la estabilidad está comprometida da y eventual relleno de las cavidades con sustancias liberadoras de antibióticos. Tras períodos prolongados de antibioterapia seleccionada según los antibiogramas de los cultivos, y una vez que se tiene la certeza de haber curado la infección, se han de plantear técnicas especiales para la reconstrucción del defecto óseo y para conseguir una adecuada cobertura de partes blandas. Estamos ante una infección asociada a implante (clavo intramedular) y pseudoartrosis de la fractura de tibia (ausencia de unió tras 11 meses). La infección se entiende por la clínica (supuración, ausencia de unión) y el antecedente de diabetes y fractura abierta. El manejo se solapa con el del manejo de una osteomielitis crónica. La antibioterapia aislada (opción 2) está indicada sólo en pacientes con grave comorbilidad en los cuales el tratamiento quirúrgico sería más agresivo que continuar con la enfermedad. La dinamización del clavo asociado a antibioterapia de amplio espectro (opción 1) tampoco, porque (a) no ha demostrado beneficio en pseudoartrosis establecidas y (b) tenemos el mismo tema que la opción 1, no eliminamos biofilm. La opción 3, discutida, se plantearía sólo si no hubiera infección asociada.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-9fa076592e47', '67c5d7abac0ed1469c02bcbd47709537ca3df111', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Hombre de 35 años, ingresado por traumatismo torácico grave con múltiples fracturas costales. Tras responder favorablemente al tratamiento con analgésicos y oxígeno, comienza a presentar hipoxemia grave.', 'Señale cuál es la causa más probable de este deterioro:', '[{"position": 1, "text": "La inestabilidad de la pared torácica por las fracturas múltiples."}, {"position": 2, "text": "La infección respiratoria por aspiración."}, {"position": 3, "text": "La alteración del intercambio gaseoso por la contusión pulmonar."}, {"position": 4, "text": "La hipovolemia postraumática."}]'::jsonb, 4, 3, 'definitiva', 'La contusión pulmonar es la lesión más grave y que condiciona peor pronóstico en un traumatismo torácico. También es la lesión que ocasiona más precozmente hipoxemia. En contra de lo que podemos pensar, el tórax inestable por fracturas costales múltiples (volet costal) ocasionaría una hipoventilación progresiva con atelectasias del parénquima pulmonar, que iría progresando por una parte en hipercapnia y acidosis respiratoria, y por otra, en hipoxemia más tardía por infección asociada a las atelectasias. La infección respiratoria por aspiración también se presentaría de forma más tardía, y en no aparece en todos los casos de traumatismo torácico grave, sólo si ha habido disminución de nivel de consciencia (TCE asociado, intubación no controlada con broncoaspiración…). La hipovolemia postraumática (en este caso, al haber fracturas costales múltiples podría deberse a un hemotórax) se produciría de forma más precoz y asociaría en primer lugar inestabilidad hemodinámica.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9cf9abe59b5d', '7ea36b725cabb722d96b874167f9b3598b005761', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de 6 años que viene a la consulta acompañado del monitor de un centro de acogida de nuestro barrio por tumoración dolorosa a la palpación de 3 cm de diámetro en zona occipital derecha del cuero cabelludo. Padece alopecia en dicha zona y 3 adenomegalias de consistencia bastante dura en región cervical posterior derecha.', '¿Qué tratamiento sería el más adecuado?', '[{"position": 1, "text": "Incisión y drenaje."}, {"position": 2, "text": "Mupirocina tópica."}, {"position": 3, "text": "Griseofulvina por vía oral."}, {"position": 4, "text": "Cefazolina intravenosa."}, {"position": 5, "text": "Ketoconazol tópico."}]'::jsonb, 5, 3, 'definitiva', 'La respuesta correcta es la 3. Si no me equivoco está describiendo un Querion de Celso para el cual el tratamiento de elección es la griseofulvina vía oral.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b7b6afab3ed9', '28e7e4d6e0d24158b93fb2f9ca473f7d38ea19c6', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 26 años que consulta por sensación de debilidad generalizada que se ha instaurado progresivamente en el curso de tres semanas, haciéndose especialmente intensa en los últimos dos días. Refiere desde hace un par de años episodios de dolor articular en las manos que han precisado de la toma de antiinflamatorios, así como la aparición de alguna lesión eritematosa de causa no aclarada en la zona del escote, principalmente en verano. En la exploración física destaca únicamente una palidez cutáneo-mucosa evidente y una frecuencia cardiaca de 100 lpm. En el hemograma destaca: Hb 6 gr/dL, Hto 27%, VCM 105 fL, 3.420 leucocitos/mm3 (2300 neutrófilos/mm3, 800 linfocitos/mm3, 250 monocitos/mm3, 50 eosinófilos/mm3, 20 basófilos/mm3), plaquetas 170.000/mm3. En la bioquímica: AST 30 UI/L, ALT 35 UI/L, GGT 59 UI/L, fosfatasa alcalina 105 UI/L, LDH 490 UI/L, urea 20 mg/dL, creatinina 0,8 mg/dL.', 'Teniendo en cuenta la información disponible, indique cuál de los siguientes parámetros analíticos adicionales necesitaría conocer para poder tomar la decisión inmediata más apropiada:', '[{"position": 1, "text": "Vitamina B12."}, {"position": 2, "text": "Anticuerpos antinucleares."}, {"position": 3, "text": "Test de Coombs directo."}, {"position": 4, "text": "Anticuerpos anti-DNA."}]'::jsonb, 4, 3, 'definitiva', 'Comentan el caso de una mujer joven con clínica de enfermedad sistémica de probable origen autoinmune (lupus) que presenta una anemia macrocítica, las opciones 2 y 4 son opciones para identificar la enfermedad autoinmune pero lo que nos piden es que hacer para tratar la anemia por lo cual debemos de sospechar es que la anemia sea secundaria a la autoinmune y por tanto solicitar un test de coombs directo, ya que si es positivo la paciente en principio salvo extrema gravedad no va a ser transfundida y se debe tratar la causa primaria. Además habla de instauración rápida, que en el caso de la vitamina B12 es más progresiva.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-856dd0c08eb9', '7465b5f6ec25d333dd9b4e82d19468b44d18b1f6', NULL, NULL, NULL, false, false, 'Pediatría', 'Lactante de 6 meses que acude a urgencias por dificultad respiratoria. Exploración: temperatura axilar 37,2°C, frecuencia respiratoria 40 rpm, frecuencia cardíaca 160 lpm, tensión arterial 90/45 mmHg, SatO2 95% con aire ambiente. Muestra dificultad respiratoria moderada con retracción intercostal y subcostal. Auscultación pulmonar: roncus espiratorios diseminados, espiración alargada y ligera disminución en la entrada de aire en ambos campos pulmonares. Auscultación cardiaca: sin soplos. Se decide mantener al paciente en observación en el hospital durante unas horas.', '¿Qué actitud considera más adecuada en este momento respecto a las pruebas complementarias?:', '[{"position": 1, "text": "Solicitar gasometría venosa, recuento leucocitario y reactantes de fase aguda."}, {"position": 2, "text": "Solicitar radiografía de tórax."}, {"position": 3, "text": "Solicitar gasometría arterial y reactantes de fase aguda."}, {"position": 4, "text": "No solicitar pruebas complementarias."}]'::jsonb, 4, 4, 'definitiva', 'El paciente probablemente presenta un cuadro de bronquiolitis. En este momento no sería necesario realizar ninguna prueba complementaria salvo empeoramiento clínico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b846a10d8eec', '10addc6866fd98c55e67f53fbcf5ad2db0a8aa96', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Mujer de 72 años sin antecedentes de interés. Tras un cólico renal complicado se encuentra casualmente en la TC abdominal una lesión quística en cola de páncreas de 2 cm, junto con múltiples lesiones quísticas renales bilaterales. La ultrasonografía endoscópica muestra una lesión poliquística formada por múltiples vesículas con calcificación central en cola de páncreas sin conexión con el conducto de Wirsung. El análisis del líquido es compatible con un cistoadenoma seroso.', 'De las siguientes, ¿cuál es la actitud más correcta con respecto al manejo de esta paciente?:', '[{"position": 1, "text": "Resección quirúrgica (pancreatectomía corporocaudal)."}, {"position": 2, "text": "Punción guiada mediante ultrasonografía endoscópica y etanolización de la misma."}, {"position": 3, "text": "Seguimiento de la lesión mediante RM."}, {"position": 4, "text": "Trasplante de riñón-páncreas."}]'::jsonb, 4, 3, 'definitiva', 'El cistoadenoma seroso de páncreas es una entidad benigna frecuentemente poliquística (también llamado adenoma microquístico) formado por células productoras de colágeno (no mucinosas). Habitualmente es asintomática y se descubre como hallazgo incidental. Dada su naturaleza benigna no se recomienda la cirugía, reservándose únicamente en aquellos sintomáticos o en los que la naturaleza de la lesión queda en entredicho después de un estudio completo con TC, RM y ecoendoscopia con biopsia. Frecuentemente es esporádico, pero se puede asociar con el síndrome de Von-Hippel-Lindau.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-31ef189a8701', '43317ac41462aae2725eb3379b8a9a2f029e5dc2', NULL, NULL, NULL, false, false, 'Endocrinología', 'Mujer de 66 años diagnosticada de diabetes mellitus tipo 2 desde hace tres meses. Tiene un IMC de 31 Kg/m2 y presenta mal control glucémico a pesar de realizar un programa de medidas no farmacológicas (alimentación saludable, ejercicio).', '¿Cuál de los siguientes fármacos hipoglucemiantes se asocia a aumento de peso y deberíamos evitar en esta paciente?:', '[{"position": 1, "text": "Metformina (biguanida)."}, {"position": 2, "text": "Pioglitazona (tiazolidindiona)."}, {"position": 3, "text": "Canagliflozina (inhibidor del cotransportador 2 de sodio-glucosa- iSGLT2)."}, {"position": 4, "text": "Liraglutida (agonista del receptor para GLP-1)."}]'::jsonb, 4, 2, 'definitiva', 'Una pregunta algo más complicada que la anterior. En cuanto al peso, la metformina en menor medidas, los inhibidores de SGLT-2 y, sobre todo, los agonistas de GLP-1, se han relacionado con una disminución significativa del peso en paciente con DM-2 (respuestas 1,3 y 4 incorrectas). En cambio, la pioglitazona, tal como refleja su ficha técnica, puede producir aumento de peso dosis-dependiente, principalmente por acumulación de grasa y añadida, en algunos casos, a la retención hídrica.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f1a363e62a36', '99bb4bc93878ad4748ad58f2807c64620eda051b', NULL, NULL, NULL, false, false, 'Nefrología', 'Ante un paciente con enfermedad renal crónica avanzada (ERC G4, FGe 20 ml/min) conocida, que acude a urgencias por debilidad general y se le detecta una hiperpotasemia grave (K 7 mEq/l) con alteraciones electrocardiográficas.', '¿Cuál sería la primera medida a tomar?:', '[{"position": 1, "text": "Administración de resinas de intercambio catiónico."}, {"position": 2, "text": "Colocación de un catéter para iniciar diálisis."}, {"position": 3, "text": "Administración de gluconato cálcico endovenoso."}, {"position": 4, "text": "Administración de furosemida oral."}]'::jsonb, 4, 3, 'definitiva', 'Nos describen el caso de un paciente con una emergencia hiperkalémica (potasio >6,5 mmol/l con alteraciones en el ECG). El primer paso es la administración de gluconato cálcico iv para contrarrestar la toxicidad cardíaca de la hiperpotasemia (opción 3 correcta), dándonos más tiempo para iniciar los tratamientos hipokalemiantes (inicialmente suero glucosado con insulina, salbutamol, furosemida, y valorando diálisis si no hay buena respuesta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-781802b43308', '0d366cdeca5e1f7abff82d3616e1bb1f4c397ef1', NULL, NULL, NULL, false, false, 'Reumatología', 'Una paciente de 45 años con antecedentes de reflujo gastroesofágico presenta desde hace un año episodios de palidez en algunos dedos de las manos con la exposición al frío. Recientemente se le había prescrito prednisona a dosis de 20 mg/día por dolor articular e induración cutánea en manos y brazos. Presenta desde hace 48 horas malestar general y cefalea intensa, por lo que acude a urgencias. En la exploración destaca únicamente una taquicardia rítmica a 100 lpm, no se aprecia focalidad neurológica. La presión arterial es de 200/110 mmHg. En la analítica destaca únicamente una creatinina de 2,5 mg/dl.', 'Indique cuál de los siguientes autoanticuerpos se relaciona mejor con el proceso descrito:', '[{"position": 1, "text": "Anticuerpos anti-RNA polimerasa III."}, {"position": 2, "text": "Anticuerpos anti-centrómero."}, {"position": 3, "text": "Anticuerpos anti-proteinasa 3."}, {"position": 4, "text": "Anticuerpos anti-PM-Scl."}]'::jsonb, 4, 1, 'definitiva', 'Se trata de un caso clínico claro de esclerosis sistémica (Raynaud, afectación esofágica, induración cutánea) que presenta una crisis renal. Quitando los Ac anti-proteinasa 3, que no se relacionan con esclerodermia (respuesta 3 incorrecta), los más probables serán los Ac antiRNA polimerasa III, que aparecen en pacientes más jóvenes y con crisis renales.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2adbc6d2aad3', 'a142913a7eb9099a8e29e425e63bcc36c3abc5df', NULL, NULL, NULL, false, false, 'Dermatología', 'Niña de 4 años que presenta fiebre alta de 6 días de evolución. En la exploración clínica presenta un exantema eritematoso maculopapular en tronco y zona genital, con tendencia a la confluencia, sin llegar a ser escarlatiniforme; inyección conjuntival sin secreciones y labios rojos con lengua aframbuesada. Presenta también eritema con edema en manos y pies y una adenopatía cervical unilateral de 2 cm de diámetro.', 'El diagnóstico clínico de sospecha más probable es:', '[{"position": 1, "text": "Enfermedad de Kawasaki."}, {"position": 2, "text": "Sarampión."}, {"position": 3, "text": "Rubeola."}, {"position": 4, "text": "Escarlatina."}]'::jsonb, 4, 1, 'definitiva', 'No hay lugar a dudas, no están dando los criterios diagnósticos de una enfermedad de Kawasaki (fiebre de varios días de evolución, exantema, inyección conjuntival, labios rojos, lengua aframbuesada, edema de partes acrales y adenopatía).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-020975c62d2c', 'cd4011cfd915ffd01e1f1370a77d9ce1c127be88', NULL, NULL, NULL, false, false, 'Nefrología', 'Varón de 58 años con antecedentes de hipertensión arterial de 6 años de evolución, que consulta por mal control de las cifras de presión arterial a pesar de recibir tratamiento con un inhibidor de la enzima convertidora en angiotensina, un diurético y un calcioantagonista. En consulta presenta cifras de 149/100 mmHg. Analítica: creatinina 1,2 mg/dl, potasio 2,2 mEq/l y alcalosis metabólica compensada; resto del estudio bioquímico, hemograma, coagulación y sedimento urinario normal.', 'Señale la afirmación correcta:', '[{"position": 1, "text": "El origen de la hipertensión en este caso es la secreción excesiva de aldosterona causada por una hiperfunción autónoma de la médula suprarrenal."}, {"position": 2, "text": "En la mayoría de los casos el sustrato anatómico es una hiperplasia bilateral de la corteza suprarrenal."}, {"position": 3, "text": "La TC forma parte del estudio diagnóstico en caso de haber una confirmación bioquímica."}, {"position": 4, "text": "La espironolactona está contraindicada en el manejo de esta patología."}]'::jsonb, 4, 3, 'definitiva', 'Nos presentan un paciente con hipertensión arterial resistente, dando por hecho que tiene un hiperaldosteronismo primario por la alcalosis metabólica hipopotasémica. Cuando está bioquímicamente confirmado el diagnóstico, la siguiente prueba a realizar es una TC para determinar el subtipo y descartar la presencia de un carcinoma suprarrenal (opción 3 correcta). Por tanto, hay que esperar a la prueba de imagen para confirmar la etiología (opción 1 incorrecta). La causa más frecuente es el adenoma productor de aldosterona (opción 2 incorrecta). La espironolactona es el tratamiento médico de elección (opción 4 incorrecta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-28ba8ce59b5b', '01a392dc4a00627e243bcbc5595fb12535124ed0', NULL, NULL, NULL, false, false, 'Endocrinología', 'Niña de 14 años que consulta por disminución del crecimiento desde hace 2-3 años previamente normal (aporta datos) y que las demás niñas de su edad tienen un mayor desarrollo físico y sexual. Últimamente tiene cefaleas y problemas visuales que nota en clase y al estudiar. No ha tenido la menarquia ni polidipsia o poliuria. Padres con talla normal. Exploración: talla baja situada en -2.1 desviaciones estándar, proporciones corporales normales, poco vello pubiano y desarrollo mamario. La campimetría muestra hemianopsia parcial temporal izquierda. Edad ósea: retraso de 2 años. Analítica general normal. Gonadotrofinas (FSH y LH) y estradiol bajos.', '¿Cuál le parece la respuesta más idónea?', '[{"position": 1, "text": "La disminución del crecimiento y desarrollo sexual, edad ósea retrasada, cefalea y alteración visual sugieren déficit hormonal y compromiso del quiasma óptico."}, {"position": 2, "text": "Al ser una niña en edad puberal, lo más probable es que su disminución de crecimiento y retraso sexual sean debidos a un síndrome de Turner."}, {"position": 3, "text": "No debe tener un tumor hipotalámico por la ausencia de poliuria y polidipsia. Seguramente tenga retraso constitucional y su problema visual sea de refracción."}, {"position": 4, "text": "Un déficit de hormona de crecimiento puede explicar el retraso del desarrollo y estradiol bajo. Valorar si precisa gafas, por sus cefaleas y alteraciones visuales."}, {"position": 5, "text": "Podría tener un craneofaringioma, pero sería raro que no hubiera dado síntomas antes. Además, no justificaría las gonadotrofinas y estradiol bajos."}]'::jsonb, 5, 1, 'definitiva', 'La respuesta 2 es falsa (Síndrome Turner: estradiol bajo y gonadotrofinas elevadas), los tumores cerebrales que afectan hipotálamo-hipófisis sin dan gonadotrofinas bajas (5 falsa), y parece obvio que los defectos de refracción no dan hemianopsia (3 y 4 falsas).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-bec22fc630f5', '6a963e99aab50d1d9e03bb28ee13ab4c7d36bff3', NULL, NULL, NULL, false, false, 'Nefrología', 'Mujer de 66 años con diabetes mellitus tipo 2. Valorando su función renal presenta un estadio G3a/A1.', '¿A qué valores corresponde este estadio, el más frecuente en pacientes con nefropatía diabética?:', '[{"position": 1, "text": "Filtrado glomerular 45-59 ml/min/1,73 m² y albuminuria <30 mg/ml."}, {"position": 2, "text": "Filtrado glomerular 30-44 ml/min/1,73 m² y albuminuria <30 mg/ml."}, {"position": 3, "text": "Filtrado glomerular 45-59 ml/min/1,73 m² y albuminuria 30-300 mg/ml."}, {"position": 4, "text": "Filtrado glomerular 15-29 ml/min/1,73 m² y albuminuria <30 mg/ml."}]'::jsonb, 4, 1, 'definitiva', 'Pregunta fácil. El estadio G3a corresponde a un filtrado entre 45-59 ml/min. El estadio A1 corresponde a una albuminuria inferior a 30 mg/ml. Por tanto la opción correcta es la 1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-40e5253b2dd2', 'ee74c0267ff62cb40ecbcb9acfc43b7da851aecc', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Mujer de 75 años traída a consulta por su familia porque le encuentran desde hace meses deprimida y con fallos de memoria. Les preocupa que pueda tener una enfermedad de Alzheimer. La paciente refiere que no cree que le pase nada y que está como siempre.', '¿En qué orden se presentan generalmente los siguientes síntomas en la progresión de la enfermedad de Alzheimer?:', '[{"position": 1, "text": "Cambios de humor, síntomas conductuales, déficit cognitivo."}, {"position": 2, "text": "Síntomas conductuales, síntomas motores, declive de la independencia funcional."}, {"position": 3, "text": "Cambios de humor, déficit cognitivo, declive de la independencia funcional."}, {"position": 4, "text": "Síntomas conductuales, cambios de humor, síntomas motores."}]'::jsonb, 4, 3, 'definitiva', 'Esta pregunta la contesto pensando más en lo que quieren preguntar que en lo que realmente preguntan. Existe heterogenicidad en el desarrollo de los síntomas de la enfermedad de Alzheimer. Existen variantes conductuales, pero en el MIR suelen querer que penséis en otro tipo de demencias ante síntomas conductuales. De hecho, la aparición de estos en fases precoces nos ha de poner en alerta y abrir el abanico de posibilidades diagnósticas. Por ello descartamos la 2 y la 4. Entre la 1 y la 3 elijo la 3 por el mismo motivo y por el hincapié al declive de la independencia funcional que se produce en estos pacientes.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-df44a9ec5b78', '76f0384255a1c5da0dce269fa80b95c3cda36ac1', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Varón de 49 años que ingresa en UCI por un traumatismo craneoencefálico tras un accidente laboral. En la exploración física no abre ojos, no emite sonidos antes de ser intubado y presenta extensión de extremidades al estímulo nociceptivo. Se coloca un sensor de presión intracraneal y debe realizarse una craneotomía descompresiva por una hemorragia intraparenquimatosa.', '¿Cuál de las siguientes afirmaciones es correcta?:', '[{"position": 1, "text": "A su llegada se encuentra en un coma de la escala de Glasgow de 7."}, {"position": 2, "text": "La presión de perfusión cerebral es la presión arterial media más la presión intracraneal."}, {"position": 3, "text": "El edema cerebral vasogénico se produce por edema celular, rotura de la membrana y muerte celular."}, {"position": 4, "text": "El flujo vascular cerebral aumenta con la hipercapnia y la acidosis."}]'::jsonb, 4, 4, 'definitiva', 'La hipercapnia y la acidosis producen vasodilatación que provocan aumento del flujo sanguíneo cerebral. Según la exploración descrita el Glasgow es de 4 (O1V1M2). La presión de perfusión cerebral es la presión arterial media menos la presión intracraneal. El edema cerebral en el que se produce edema celular por introducción de líquido extracelular a compartimento intracelular es el citotóxico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fc0ba0a3aaf8', 'af44537cc9d99dcbc10cb934fa2476ea97183c85', NULL, NULL, NULL, false, false, 'Oncología', 'Mujer de 40 años que consulta porque desde hace un mes se nota un bulto en el cuadrante superoexterno de la mama derecha. Aporta un informe de una mamografía que describe una lesión BIRADS 3.', '¿Cuál es la actitud a seguir?:', '[{"position": 1, "text": "Tranquilizarle, puesto que ya se ha hecho una prueba de imagen y se ha descartado malignidad."}, {"position": 2, "text": "Esa clasificación implica probablemente cirugía dado que la probabilidad de cáncer es mayor del 10%. Se lo explica y le deriva de forma preferente a la Unidad de Mama."}, {"position": 3, "text": "Se trata de un hallazgo probablemente benigno, dado que hay menos de un 2% de probabilidad de cáncer. Le explica que requiere de un seguimiento cada 6-12 meses hasta los 24 meses o una biopsia."}, {"position": 4, "text": "Los hallazgos son de baja sospecha de cáncer (entre un 2 y un 10%) pero es necesario hacer una biopsia."}]'::jsonb, 4, 3, 'definitiva', 'BI-RADS Breast Imaging Reporting and Data System. BI-RADS 3 se define con la respuesta 3.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d033c9add068', '6c8b97ca19bf725b1117403c064197fb4e78a706', NULL, NULL, NULL, false, false, 'Pediatría', 'Lactante de 2 meses de edad con catarro de vías altas de 3 días de evolución, que comienza con dificultad respiratoria moderada y auscultación pulmonar con sibilancias espiratorias. La saturación de oxígeno es de 89%. Se aísla virus respiratorio sincitial en el exudado nasofaríngeo.', '¿Cuál de los siguientes tratamientos considera más indicado para este cuadro?:', '[{"position": 1, "text": "Rivabirina oral."}, {"position": 2, "text": "Salbutamol nebulizado."}, {"position": 3, "text": "Oxígeno suplementario."}, {"position": 4, "text": "Corticoides intravenosos."}]'::jsonb, 4, 3, 'definitiva', 'Nos presentan el caso de una bronquiolitis VRS positivo. Según las recomendaciones actuales, lo indicado sería iniciar oxigenoterapia suplementaria.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fdc0c03463e2', '076e12328ce7910b5d6941ac788b5b51e9351b06', NULL, NULL, NULL, false, false, 'Reumatología', 'Varón de 67 años que presenta un cuadro de 3 meses de duración de astenia y febrícula, a la que se añade en el último mes obstrucción nasal con emisión de moco con algunos coágulos. En los últimos días nota dolor en el ojo derecho y asimetría respecto al contralateral. En la exploración física se objetiva proptosis del globo ocular derecho y la inspección de las fosas nasales constata una mucosa eritematosa con costras serohemáticas. El resto de la exploración es normal. Los análisis de sangre (hemograma, función renal y hepática) son normales, a excepción de una VSG de 65 mm/h; en el análisis de orina se detecta microhematuria y proteinuria de 520 mg/24h.', '¿Cuál es el diagnóstico inicial más probable?', '[{"position": 1, "text": "Granulomatosis eosinofílica con poliangitis."}, {"position": 2, "text": "Poliangitis microscópica."}, {"position": 3, "text": "Granulomatosis con poliangitis."}, {"position": 4, "text": "Poliarteritis nudosa."}]'::jsonb, 4, 3, 'definitiva', 'En este paciente, presenta una granulomatosis con poliangitis antes conocida como granulomatosis de Wegener. Nos comentan en el caso clínico la afectación otorrinolaringológica que está presente en el 92% de los pacientes. A nivel pulmonar nos comenta que ha presentado moco con algún coágulo, este tipo de afectación está presente en el 85% de los pacientes. También al acabar el caso, nos comentan el análisis de orina con una glomerulonefritis que están presentes en el 77% de los pacientes.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c83f0892a06e', '92bb34ba4c9659053b6d093cbeea27a3c5d5c125', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 13 años, sin antecedentes relevantes, con menarquia hace 3 meses, seguida desde los 10 años por escoliosis idiopática que ha empeorado. En la exploración física presenta una giba de 7 grados en el test de Adams y en el escoliograma una curva toracolumbar T4-L1 de 35 grados de Cobb y un Risser 0.', 'La actitud correcta a tomar será:', '[{"position": 1, "text": "Recomendar natación y revisión en tres meses."}, {"position": 2, "text": "Prescribir una ortesis tipo corsé."}, {"position": 3, "text": "Derivar a fisioterapia para elastificación del raquis."}, {"position": 4, "text": "Revisar en 6 meses con una nueva radiografía."}]'::jsonb, 4, 2, 'definitiva', 'Ortesis. Angulo de Cobb entre 25º – 45º. Esqueleto inmaduro (Risser 0).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a1c7eaae0eef', 'be146ab5fa16191075df8c1fcf03a4cc1b6c231d', NULL, NULL, NULL, false, false, 'Oftalmología', 'Paciente de 20 años que acude a urgencias tras sufrir un accidente de bicicleta con traumatismo facial. Se realiza TC craneal que muestra una fractura del tercio medio facial que afecta a la región órbito-malar.', 'Una de las complicaciones más frecuentes de este tipo de fracturas es:', '[{"position": 1, "text": "Anquilosis témporo-mandibular."}, {"position": 2, "text": "Maloclusión dental."}, {"position": 3, "text": "Pseudoartrosis naso-etmoidal."}, {"position": 4, "text": "Enoftalmos."}]'::jsonb, 4, 4, 'definitiva', 'Las fracturas del tercio medio facial en la región orbito-malar pueden afectar al suelo y, en menor medida, a la pared lateral de la órbita. Asumiendo por tanto que nos preguntan cuál es una de las complicaciones más frecuentes del suelo de la órbita, deben destacarse siempre dos complicaciones que pueden indicar tratamiento quirúrgico, incluso urgente: la diplopía, por luxación del músculo recto inferior al seno maxilar infrayacente (e incluso atrapamiento del mismo); y el enoftalmos, que puede condicionar a medio y largo plazo otras complicaciones asociadas, como la pseudo-ptosis palpebral superior por pérdida de volumen orbitario (opción 4 correcta). La anquilosis temporo-mandibular no se contempla porque, aunque relativamente cercana a la cavidad orbitaria, no forma parte del complejo órbito-malar (opción 1 descartada). La afectación del maxilar puede dar lugar a maloclusión dental, pero normalmente ocurre en fracturas de localización más inferior a la cavidad orbitaria (opción 2 descartada). Las fracturas naso-etmoidales se contemplan dentro de las fracturas del tercio medio facial, pero los huesos propios de la nariz se localizan más anteriormente al reborde orbitario medial, y por consiguiente fuera de la órbita (opción 3 descartada).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9655650ac415', 'ed45243e96d296c9e8b07692e112198d21e37248', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Nos consultan para valorar una mujer de 83 años que ha ingresado en el servicio de Traumatología por una fractura de cadera hace 6 horas. Tiene AP de HTA, DL, demencia moderada y vive en una residencia. Su tratamiento habitual es tiazida, atorvastatina, donepezilo, Calcio y vitamina D. EF: Paciente confusa, pulso 90 lpm, frec respiratoria 20 rpm, T art 170/88, presión venosa yugular normal. La analítica y la Rx de tórax son normales y el ECG muestra un ritmo sinusal sin alteraciones isquémicas.', '¿Cuál de las siguientes es la actitud terapéutica más correcta?', '[{"position": 1, "text": "Retrasar la cirugía hasta que haya desaparecido el cuadro confusional."}, {"position": 2, "text": "Retrasar la cirugía y realizar un ecocardiograma."}, {"position": 3, "text": "Retrasar la cirugía hasta buen control de la tensión arterial."}, {"position": 4, "text": "Iniciar un betabloqueante e iniciar la cirugía."}, {"position": 5, "text": "Realizar osteosíntesis cerrada, evitando en todo caso la implantación de prótesis."}]'::jsonb, 5, 4, 'definitiva', 'El cuadro confusional está determinado por la demencia que ya sufre la paciente, así que por mucho que retrasemos la cirugía, no vamos a conseguir nada. La elevación de la tensión arterial se debe, en principio, al dolor (por lo que la primera opción es un analgésico) y, luego, a la situación de estrés que lleva a una paciente ya hipertensa a aumentar su tensión arterial, por lo que el labetalol podría ayudarnos. La última respuesta no es correcta porque depende del tipo de fractura, que no nos especifican en el enunciado: una pertrocantérea, necesitaría osteosíntesis cerrada y una subcapital, una prótesis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8cf2bf293d6f', 'a4d13ec44dc74fba02fb0c39ac5588fc2c8f747d', NULL, NULL, NULL, false, false, 'Ciencias Básicas', 'Una mujer de 42 años con cáncer de mama presenta metástasis a nivel de los agujeros intervertebrales entre la 4ª y 5ª vértebras cervicales y entre la 4ª y 5ª vértebras torácicas.', '¿Qué nervios espinales estarán lesionados?', '[{"position": 1, "text": "Cuarto nervio cervical y cuarto torácico."}, {"position": 2, "text": "Quinto nervio cervical y quinto torácico."}, {"position": 3, "text": "Cuarto nervio cervical y quinto torácico."}, {"position": 4, "text": "Quinto nervio cervical y cuarto torácico."}, {"position": 5, "text": "Tercer nervio cervical y cuarto torácico."}]'::jsonb, 5, 4, 'definitiva', 'El truco de esta pregunta es que hay 8 raíces cervicales para 7 vértebras, por tanto la raíz C1 sale POR ENCIMA del atlas, y así hasta C8 que sale ENTRE C7 y T1. Las raíces torácicas salen respectivamente por debajo de la vértebra con su misma numeración (nervio T1 bajo T1, T2 bajo T2, etc.). Por tanto, entre C4 y C5 sale el 5º nervio cervical, y entre T4 y T5 el 4º torácico. La respuesta correcta es la 4.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8bf7217dedb3', '279027ccf5c79544779f3baebdf23bb533dd5296', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Un paciente con antecedentes de cuadro febril y dolor torácico acude al hospital con disnea y taquipnea. En la exploración física las cifrad de presión arterial están bajas, la presión venosa yugular está elevada con un seno X descendiente profundo y tiene pulso paradójico.', 'Que patología debe sospechar?', '[{"position": 1, "text": "Cardiopatía isquémica."}, {"position": 2, "text": "Miocardiopatía dilatada."}, {"position": 3, "text": "Estenosis valvular aórtica severa."}, {"position": 4, "text": "Pericarditis constrictiva."}, {"position": 5, "text": "Derrame pericárdico con taponamiento cardiaco."}]'::jsonb, 5, 5, 'definitiva', 'La PA baja con Presión yugular alta debe hacer siempre sospechar un taponamiento cardiaco. El cuadro febril y dolor torácico con disnea y taquipnea deben hacer sospechar un derrame pericárdico con compromiso hemodinámica. El pulso paradójico es un hallazgo típico de taponamiento cardiaco. Por tanto la respuesta correcata es la 5.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ed0020b37aa2', '715bf783eda83b843bcd7bba472a62de4d1bf283', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Un paciente ingresado por pancreatitis aguda comienza con taquipnea, taquicardia, sudoración y cianosis progresiva. La PaO2 es de 55 mm Hg (cociente PaO2/FiO2<200). LA RxT muestra infiltrados pulmonares alveolares bilaterales. La presión de enclavamiento capilar pulmonar es normal. La oxigenoterapia no mejora la situación.', 'Que diagnóstico es el mas probable:', '[{"position": 1, "text": "Neumonía nosocomial."}, {"position": 2, "text": "Insuficiencia cardiaca."}, {"position": 3, "text": "Linfangitis carcinomatosa."}, {"position": 4, "text": "Tromboembolismo pulmonar."}, {"position": 5, "text": "Distress respiratorio."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta con respuesta directa. La pregunta cuenta el caso de un paciente con una pancreatitis aguda que está desarrollando un cuadro de insuficiencia respiratoria aguda. En el enunciado se enumeran los criterios de SDRA (síndrome de distrés respiratorio agudo): PaO2/fiO2 < 200 + infiltrados pulmonares bilaterales + PCP<18. Por lo que el diagnóstico es distrés respiratorio y por tanto la respuesta correcta es la opción 5.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c4ecdcb5091a', '3a9558e26c7b592e4371ea15510f2acd571f8c0a', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Durante una colonoscopia se detecta un tumor de 5 cm localizado en colon derecho en un hombre de 48 años. No se han encontrado otras lesiones. Su abuela materna también padeció un cáncer de colon.', 'Las biopsias son superficiales y muestran un tumor pobremente diferenciado con abundantes células inflamatorias en el estroma que se diagnostica como un carcinoma de tipo medular.', '[{"position": 1, "text": "La quimioterapia es el tratamiento de elección."}, {"position": 2, "text": "Puesto que la biopsia es superficial debe repetirse antes de proceder al tratamiento."}, {"position": 3, "text": "El pronóstico del tumor depende principalmente de su alto grado de anaplasia."}, {"position": 4, "text": "Es poco probable que este tumor se haya desarrollado sobre un adenoma previo."}, {"position": 5, "text": "Debe estudiarse la inestabilidad de microsatélites, y los genes de reparación de errores del DNA."}]'::jsonb, 5, 5, 'definitiva', 'Pegunta complicada sobre un adenocarcinoma poco habitual. Por descarte, la 1 sería fácil de eliminar, el tratamiento del cáncer de colon es quirúrgico (con neoadyuvancia en los de recto). Las biopsias si confirman adenocarcinoma no hace falta repetirla, ya que lo necesario es tener la pieza completa. La mayor parte de los ca. de colon se desarrollan sobre adenomas con lo cual esta la podríamos eliminar. Entre las otras 2 hay que saber que la 5 es correcta ya que suelen presentar casi siempre inestabilidad de microsatélites incluso sin cumplir criterios de Amsterdam y tienen mejor pronóstico frente a otros ca de colon poco diferenciados.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fe9787428866', '0fd5cc94338519ef78d2901a196e2e3fc86095f3', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Mujer de 52 años que consulta copor haber notado durante la semana previa coloración amarillenta de conjuntivas. No refiere conductas sexuales de riesgo ni antecedente epidemiológicos de riesgo de hepatitis víricas. No consume alcohol ni fármacos hepatotóxicos. Relata historia de un año de evolución de prurito generalizado, astenia, sequedad de boca y ausencia de lagrimeo de causa no filiada. Resto de la anamnesis sin datos patológicos. En la exploración física se observan lesiones de rascado, ictericia conjuntival y hepatomegalia no dolorosa. Aporta analítica realizada en su empresa con los siguientes resultados patológicos: Bilirrubina 3 mg/dl, FA 400 UI/ VSG 40mm 1 hora.', 'Indique cual sería la recomendación más acertada para establecer el diagnóstico etiológico del cuadro que presenta la paciente:', '[{"position": 1, "text": "Anticuerpos antimitocondriales."}, {"position": 2, "text": "Estudio del metabolismo del Fe."}, {"position": 3, "text": "Estudio del metabolismo del cobre."}, {"position": 4, "text": "Resonancia magnética hepática."}, {"position": 5, "text": "Serología de virus B y C."}]'::jsonb, 5, 1, 'definitiva', 'Cuadro de libro de Cirrosis Biliar Primaria, de esos que no se presentan en la vida real. El diagnóstico estaría prácticamente hecho con los AMA (1). Con la 2 descartaríamos hemocromatosis, Con la 3 la enfermedad de Wilson. Con la 4 podríamos descartar enfermedades raras tipo malformaciones de vía biliar o enf. de Caroli y con la 5 las hepatitis víricas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
